window.TXB=window.TXB||{};TXB["alab/2Ki"]={"1:1":"وتمرد الموآبيون على إسرائيل بعد وفاة أخآب،","1:2":"وسقط أخزيا من كوة في علية قصره في السامرة، فأصيب بجرح قاتل. وبعث رسلا إلى معبد بعل زبوب إله عقرون قائلا: «امضوا واسألوه إن كنت أبرأ من جرحي؟»","1:3":"فقال ملاك الرب لإيليا التشبي: «قم واذهب للقاء رسل ملك السامرة وقل لهم: هل لأنه لا يوجد إله في إسرائيل تذهبون لسؤال بعل زبوب إله عقرون؟","1:4":"لذلك هذا ما يقوله الرب: إن السرير الذي رقدت عليه لن تنهض عنه، بل حتما تموت». وانصرف إيليا.","1:5":"ورجع الرسل إلى أخزيا فسألهم: «لماذا رجعتم؟»","1:6":"فأجابوه: «اعترضنا رجل وأمرنا أن نرجع إليك لنخبرك أن الله يقول: هل لأنه لا يوجد إله في إسرائيل ترسل لتسأل بعل زبوب إله عقرون؟ لذلك فإن السرير الذي رقدت عليه لن تنهض عنه بل حتما تموت».","1:7":"فسألهم: «ما هي أوصاف الرجل الذي اعترضكم وبلغكم هذا الكلام؟»","1:8":"فأجابوه: «إنه رجل كثيف الشعر متنطق بحزام من جلد حول حقويه». فقال: «إنه حتما إيليا التشبي».","1:9":"فأرسل أحد قادته على رأس خمسين جنديا إلى إيليا، الذي كان جالسا آنئذ على قمة جبل. فقال له: «يارجل الله، إن الملك يأمرك بمرافقتنا».","1:10":"فأجاب إيليا: «إن كنت أنا رجل الله، فلتنزل نار من السماء وتلتهمك أنت ورجالك الخمسين». فنزلت نار من السماء والتهمته مع رجاله الخمسين.","1:11":"فعاد أخزيا وأرسل إليه قائدا آخر على رأس خمسين جنديا، فقال لإيليا: «يارجل الله، الملك يأمرك أن تسرع وتنزل».","1:12":"فأجابه إيليا: «إن كنت أنا رجل الله، فلتنزل نار من السماء وتلتهمك أنت ورجالك الخمسين». فنزلت نار من السماء والتهمته مع رجاله الخمسين.","1:13":"ثم أرسل أخزيا للمرة الثالثة قائدا آخر على رأس خمسين جنديا. فأقبل هذا إلى إيليا وجثا أمامه وتوسل إليه قائلا: «يارجل الله، لتكن نفسي ونفوس عبيدك هؤلاء عزيزة في عينيك.","1:14":"لقد نزلت نار من السماء التهمت القائدين السابقين مع رجالهما المئة، فأرجوك لتكن نفسي عزيزة في عينيك (ولا تقض علينا(».","1:15":"فقال ملاك الرب لإيليا: «امض معه ولا تخف منه». فقام وانطلق معه لمقابلة الملك.","1:16":"وقال إيليا للملك: «هذا ما يقوله الرب: من حيث أنك أرسلت مبعوثين لتستشير بعل زبوب إله عقرون وكأنه لا يوجد إله في إسرائيل لتسأله، فإن السرير الذي رقدت عليه لن تنهض عنه، بل حتما تموت».","1:17":"فمات أخزيا بموجب كلام الرب الذي نطق به على لسان إيليا. وإذ لم يكن له ابن، خلفه أخوه يهورام، وذلك في السنة الثانية لحكم يهورام بن يهوشافاط ملك يهوذا.","1:18":"أما بقية أخبار أخزيا وأعماله أليست هي مدونة في كتاب أخبار ملوك إسرائيل؟","2:1":"وعندما أزمع الرب أن ينقل إيليا في العاصفة إلى السماء، ذهب إيليا وأليشع من الجلجال.","2:2":"فقال إيليا لأليشع: «امكث هنا لأن الرب قد أوفدني إلى بيت إيل». فأجاب أليشع: «حي هو الرب، وحية هي نفسك إني لا أتركك». فانطلقا معا إلى بيت إيل.","2:3":"فخرج بنو الأنبياء المقيمون في بيت إيل للقاء أليشع وقالوا له: «هل تعلم أن الرب سيأخذ اليوم منك سيدك إيليا؟» فأجاب: «نعم، إني أعلم، فاصمتوا».","2:4":"ثم قال له إيليا: «ياأليشع، امكث هنا لأن الرب قد أوفدني إلى أريحا». فأجابه: «حي هو الرب وحية هي نفسك إني لا أتركك». فتوجها نحو أريحا.","2:5":"وعندما بلغاها تقدم بنو الأنبياء المقيمون في أريحا من أليشع قائلين: «أتعلم أن الرب سيأخذ اليوم منك سيدك إيليا؟» فقال: «نعم، إني أعلم فاصمتوا».","2:6":"ثم قال له إيليا: «امكث هنا لأن الرب قد أوفدني إلى الأردن». فأجاب: «حي هو الرب وحية هي نفسك إني لا أتركك». فانطلقا معا.","2:7":"ورافقهما خمسون رجلا من بني الأنبياء إلى حيث كانا يقفان إلى جوار الأردن. وتوقفوا تجاههما من بعيد.","2:8":"فتناول إيليا رداءه وطواه، ثم ضرب به الماء، فانفلق النهر إلى شطرين، فاجتازا فوق اليابسة.","2:9":"ولما عبرا قال إيليا لأليشع: «اطلب ماذا أصنع لك قبل أن أوخذ منك؟» فأجاب أليشع: «ليحل علي ضعف ما لديك من قوة روحية».","2:10":"فقال إيليا: «لقد طلبت أمرا صعبا، ولكن إن رأيتني وأنا أوخذ منك تنل سؤلك، وإلا فلن تحصل على ما طلبت».","2:11":"وفيما هما يسيران ويتجاذبان أطراف الحديث، فصلت بينهما مركبة من نار تجرها خيول نارية، نقلت إيليا في العاصفة إلى السماء.","2:12":"ورأى أليشع ما جرى فأخذ يهتف: «ياأبي، ياأبي، يامركبات إسرائيل وفرسانها». وغاب إيليا عن عينيه، فأمسك ثيابه ومزقها قطعتين،","2:13":"ثم رفع رداء إيليا الذي سقط منه وتوجه نحو ضفة نهر الأردن،","2:14":"وضرب به الماء هاتفا: «أين هو الرب إله إيليا؟» ثم ضرب الماء ثانية، فانفلق النهر إلى شطرين متقابلين، فاجتاز أليشع نحو الضفة الأخرى.","2:15":"ولما شاهده بنو الأنبياء المقيمون في أريحا قادما نحوهم قالوا: «إن روح إيليا قد استقرت على أليشع». فأقبلوا للقائه وانحنوا أمامه.","2:16":"وقالوا له: «إن بين عبيدك خمسين رجلا من ذوي البأس، فدعهم يذهبون للبحث عن سيدك. لعل روح الرب حمله وطرحه على أحد الجبال أو في أحد الأودية». فأجاب: «لا ترسلوا أحدا».","2:17":"فألحوا عليه حتى اعتراه الخجل فأذعن لهم، فأوفدوا خمسين رجلا ظلوا يبحثون عنه ثلاثة أيام على غير طائل.","2:18":"وعندما رجعوا إليه في أريحا قال لهم: «أما قلت لكم لا تبحثوا عنه؟»","2:19":"وقال رجال مدينة أريحا لأليشع: «هوذا المدينة كما ترى ذات موقع جيد، أما المياه فرديئة والأرض مجدبة».","2:20":"فقال: «أحضروا لي صحنا، وضعوا فيه ملحا». فأتوا إليه بما طلب.","2:21":"فاتجه نحو نبع الماء وطرح فيه الملح، وقال: «هذا ما تكلم به الرب: لقد أبرأت هذه المياه فلن تسبب الموت أو الجدب بعد الآن».","2:22":"فبرئت المياه إلى هذا اليوم، كما أنبأ أليشع.","2:23":"ثم ارتحل من هناك إلى بيت إيل، وفيما هو سائر في طريقه خرج بعض الفتيان الصغار من المدينة وشرعوا يسخرون منه قائلين: «اصعد (في العاصفة) ياأقرع!»","2:24":"فالتفت وراءه وتفرس فيهم، ثم دعا عليهم باسم الرب. فخرجت دبتان من الغابة والتهمتا منهم اثنين وأربعين فتى.","2:25":"وانطلق من هناك إلى جبل الكرمل ومنه رجع إلى السامرة.","3:1":"وفي السنة الثامنة عشرة من حكم يهوشافاط ملك يهوذا، اعتلى يهورام بن أخآب عرش إسرائيل، ودام ملكه في السامرة اثنتي عشرة سنة.","3:2":"وارتكب الشر في عيني الرب، ولكنه لم يوغل فيه مثلما أوغل أبوه وأمه، فإنه أزال تمثال البعل الذي نصبه أبوه.","3:3":"غير أنه تشبث بخطايا يربعام بن نباط الذي استغوى إسرائيل لارتكاب الإثم، ولم يحد عنها.","3:4":"وكان ميشع ملك موآب يقوم بتربية المواشي، ويؤدي لملك إسرائيل مئة ألف خروف ومئة ألف كبش مع أصوافها.","3:5":"وما إن توفي أخآب حتى تمرد ملك موآب على إسرائيل،","3:6":"فحشد الملك يهورام جيوشه من كل إسرائيل.","3:7":"وبعث يهورام إلى يهوشافاط ملك يهوذا قائلا: «قد تمرد ملك الموآبيين علي، فهل تشترك معي في محاربته؟» فأجابه: «أشترك، فمثلي مثلك وشعبي كشعبك وخيلي كخيلك».","3:8":"فسأله: «أي طريق نتخذ؟» فأجابه يهوشافاط: «طريق صحراء أدوم».","3:9":"فتوجه ملك إسرائيل برفقة حليفيه: ملك يهوذا وملك أدوم، وداروا في الصحراء مسيرة سبعة أيام. ولم يكن هناك ماء ليشرب الجيش والدواب التابعة لهم.","3:10":"فقال ملك إسرائيل: «هل دعانا الرب، نحن الملوك الثلاثة، ليسلمنا ليد ملك موآب؟»","3:11":"فسأل يهوشافاط: «أليس هنا نبي للرب، فنطلب مشورة الرب عن يده؟». فأجاب واحد من رجال ملك إسرائيل: «هنا أليشع بن شافاط الذي كان خادما للنبي إيليا».","3:12":"فقال يهوشافاط: «عنده كلام الرب». فتوجه إليه ملك إسرائيل ويهوشافاط وملك أدوم.","3:13":"فقال أليشع لملك إسرائيل: «ما شأني بك؟ اذهب واستشر أنبياء أبيك وأنبياء أمك». فأجابه ملك إسرائيل: «كلا إذ يبدو أن الرب قد دعانا نحن الملوك الثلاثة ليسلمنا ليد ملك موآب».","3:14":"فقال أليشع: «حي هو الرب القدير الذي أنا ماثل أمامه، إنه لولا توقيري لحضور يهوشافاط ملك يهوذا لما كنت أعبأ بالنظر إليك.","3:15":"والآن ادعوا عازف عود». وعندما عزف الموسيقى على عوده حل روح الرب على أليشع،","3:16":"فقال: «هذا ما يقوله الرب: احفروا في هذا الوادي حفرا كثيرة وعميقة،","3:17":"ومع أنكم لن تروا ريحا ولا مطرا فإن هذا الوادي سيفيض بالماء، فتشربون أنتم وماشيتكم وبهائمكم.","3:18":"وهذا أمر يسير لدى الرب، وهو أيضا ينصركم على ملك موآب.","3:19":"فتدمرون كل مدينة محصنة، وكل مدينة رئيسية، وتقطعون كل شجرة مثمرة، وتردمون كل عيون الماء، وتخربون كل حقل خصب بالحجارة».","3:20":"وفي الصباح، في ميعاد تقديم المحرقة دوى هدير مياه متدفقة من طريق أدوم، ففاضت الأرض بالمياه.","3:21":"وعندما علم الموآبيون أن الملوك الثلاثة اجتمعوا لمحاربتهم جندوا كل قادر على حمل السلاح من الصغار والكبار، واحتشدوا عند الحدود.","3:22":"وحين بكروا في صبيحة اليوم التالي رأوا أشعة الشمس منعكسة على المياه أمامهم، فبدت لهم حمراء كالدم.","3:23":"فظنوها دما وقالوا: «قد تحارب الملوك معا، وقتل بعضهم بعضا. فهيا إلى النهب أيها الموآبيون».","3:24":"فانطلقوا إلى معسكر إسرائيل، فهب الإسرائيليون وهاجموهم ففروا أمامهم، فتعقبهم الإسرائيليون إلى بلادهم وهم يقتلونهم.","3:25":"وهدموا المدن. وراح كل واحد من أفراد الجيش يلقي حجرا في كل حقل خصب حتى ملأوها، وردموا جميع عيون الماء، وقطعوا كل شجرة مثمرة، ولم تسلم إلا العاصمة «قير حارسة» التي حاصرتها وهاجمتها فرق المجانيق.","3:26":"فلما رأى ملك موآب أن المعركة اشتدت عليه اختار سبع مئة رجل من المحاربين بالسيوف ليقوم بمحاولة شق طريقه ليهاجم ملك أدوم، فلم يفلح.","3:27":"فأخذ ابنه البكر الذي كان سيخلفه على العرش، وأحرقه على السور قربانا لإله موآب، مما أثار الغيظ الشديد على إسرائيل فارتد الإسرائيليون إلى بلادهم.","4:1":"واستغاثت إحدى نساء بني الأنبياء بأليشع قائلة: «عبدك زوجي توفي، وأنت تعلم أنه كان يتقي الرب، وقد أقبل مدينه المرابي ليسترق ولدي (لقاء ديونه)».","4:2":"فسألها أليشع: ماذا يمكن أن أصنع لك؟ أخبريني ماذا عندك في البيت؟» فقالت: «لا أملك في البيت شيئا سوى قليل من الزيت».","4:3":"فقال لها أليشع: «اذهبي استعيري أواني فارغة من عند جميع جيرانك وأكثري منها.","4:4":"ثم ادخلي بيتك وأغلقي الباب على نفسك وعلى بنيك، وصبي زيتا في جميع هذه الأواني، وانقلي ما يمتليء منها إلى جانب».","4:5":"فمضت من عنده وأغلقت الباب على نفسها وعلى أبنائها، الذين راحوا يحضرون لها الأواني الفارغة فتصب فيها.","4:6":"وحين امتلأت جميع الأواني قالت لابنها: «هات إناء آخر». فأجابها: «لم يبق هناك إناء». عندئذ توقف تدفق الزيت.","4:7":"فجاءت إلى رجل الله وأخبرته. فقال لها: «اذهبي وبيعي الزيت وأوفي دينك، وعيشي أنت وأبناؤك بما يتبقى من مال».","4:8":"وذات يوم ذهب أليشع إلى شونم حيث تقيم امرأة بالغة الثراء، فألحت عليه أن يمكث ليأكل طعاما. وكان كلما زار شونم تستضيفه في منزلها.","4:9":"فقالت لزوجها: «لقد أدركت أن الرجل الذي نستضيفه دائما هو رجل مقدس لله،","4:10":"فلنبن له علية صغيرة على سطح البيت، ونعد له فيها سريرا وطاولة وكرسيا وسراجا، فيبيت فيها كلما مر بنا».","4:11":"واتفق أن جاء أليشع إلى العلية وارتاح فيها.","4:12":"فقال لغلامه جيحزي: «ادع هذه الشونمية» فاستدعاها وجاءت.","4:13":"فقال لجيحزي: «قل لها: لقد تكبدت كل هذه المشقة من أجلنا، فماذا يمكن أن أصنع لك؟ هل لديك طلب أرفعه إلى الملك أو إلى رئيس الجيش؟» فأجابت: «لا. إنني راضية بالإقامة بين شعبي».","4:14":"ثم تساءل: «ماذا يمكن أن نصنع لها؟» فأجابه جيحزي: «ليس لها ابن، وزوجها طاعن في السن».","4:15":"فقال أليشع: «استدعها». فدعاها، فوقفت عند الباب.","4:16":"فقال لها أليشع: «في مثل هذا الوقت من السنة القادمة ستحضنين ابنا بين ذراعيك». فقالت: «لا ياسيدي رجل الله. لا تخدع أمتك».","4:17":"ولكنها حملت وأنجبت ابنا في الزمن الذي أنبأ به أليشع.","4:18":"وكبر الصبي. وذات يوم انطلق إلى حيث كان أبوه يشرف على الحصادين،","4:19":"وما لبث أن قال لأبيه: «رأسي يؤلمني، رأسي». فقال لأحد رجاله: «احمله إلى أمه».","4:20":"فحمله إلى أمه فأجلسته في حجرها، ولكنه مات عند الظهر.","4:21":"فصعدت إلى العلية وأرقدته على سرير رجل الله، وأغلقت عليه الباب ثم خرجت.","4:22":"وقالت لزوجها: «ابعث لي بأحد رجالك مع أتان لأهرع إلى رجل الله ثم أرجع».","4:23":"فسألها: «لماذا تذهبين إليه اليوم، مع أنه ليس رأس الشهر ولا سبتا؟» فأجابت: «للخير!»","4:24":"وأسرجت الأتان وقالت لغلامها: «قد الأتان ولا تبطيء في السير حفاظا على راحتي حتى أطلب منك ذلك».","4:25":"وانطلقت حتى أقبلت على رجل الله في جبل الكرمل. فلما شاهدها من بعيد، قال لغلامه جيحزي: «ها هي المرأة الشونمية.","4:26":"فا ركض للقائها الآن واسألها: أهي بخير؟ هل زوجها سالم؟ هل ابنها سالم؟» فأجابت: «كل شيء بخير».","4:27":"فلما جاءت إلى رجل الله في الجبل تشبثت بقدميه. فاقترب منها جيحزي ليبعدها عنه، فقال رجل الله: «اتركها، فإن نفسها مريرة في داخلها والرب لم يكشف لي ما بها».","4:28":"فقالت: «هل طلبت من سيدي أن أنجب ابنا؟ ألم أقل لا تخدعني؟»","4:29":"فأمر أليشع جيحزي: «تمنطق بحزامك، وخذ عكازي وانطلق. وإذا صادفت أحدا فلا تحيه، وإن حياك أحد فلا تجبه. وضع عكازي على وجه الصبي».","4:30":"فقالت أم الصبي: «حي هو الرب، وحية هي نفسك إنني لا أتركك». فقام وتبعها.","4:31":"وسبقهما جيحزي ووضع العكاز على وجه الصبي، ولكن من غير جدوى فرجع للقاء أليشع وقال: «لم ترتد الحياة إلى الصبي».","4:32":"ودخل أليشع البيت وإذا بالصبي ميت في سريره.","4:33":"فدخل العلية وأغلق الباب وتضرع إلى الرب،","4:34":"ثم اضطجع فوق جثة الصبي، ووضع فمه على فمه، وعينيه على عينيه، ويديه على يديه، وتمدد عليه، فبدأ الدفء يسري في جسد الصبي.","4:35":"فأخذ النبي يذرع أرض العلية ثم عاد وتمدد على الولد، فعطس هذا سبع مرات وفتح عينيه.","4:36":"فاستدعى جيحزي وقال: «ادع هذه الشونمية». وعندما مثلت أمامه قال: «احملي ابنك!»","4:37":"فسجدت على وجهها إلى الأرض عند قدميه ثم حملت ابنها وانصرفت.","4:38":"ورجع أليشع إلى الجلجال. بعد ذلك عمت المجاعة البلاد. وفيما كان بنو الأنبياء مجتمعين مع أليشع، قال لخادمه: «اسلق بعض السليقة في القدر الكبيرة لبني الأنبياء».","4:39":"وانطلق واحد منهم ليلتقط بعض الخضروات، فعثر على يقطين بري سام، فالتقط منه ملء ثوبه، وقطعه وطرحه في قدر السليقة، غير عالم أنه سام.","4:40":"وصبوا للقوم ليأكلوا، ولكن ما إن تناولوا منه حتى صرخوا: «في القدر سم يارجل الله». ولم يستطيعوا الأكل.","4:41":"فقال: «هاتوا دقيقا» وألقى أليشع الدقيق في القدر، ثم قال: «صب للقوم ليأكلوا». فأقبلوا على الطعام وكأنه لم يكن شيء مؤذ في القدر.","4:42":"وحضر رجل من بعل شليشة حاملا معه لرجل الله عشرين رغيفا من الشعير، من أوائل الحصاد وسويقا في جرابه. فقال: «أعط الرجال ليأكلوا».","4:43":"فقال خادمه: «ماذا؟ هل أضع هذا أمام مئة رجل؟» فقال أليشع: «أعط الرجال ليأكلوا، لأنه هذا ما يقول الرب: إنهم يأكلون منها ويفضل عنهم».","4:44":"فوضعها أمامهم فأكلوا، وفضل عنهم حسب قول الرب.","5:1":"وكان نعمان قائد جيش ملك أرام يتمتع بمكانة سامية عند سيده لأن الرب حقق لأرام النصر عن يده. وكان نعمان بطلا صنديدا، إلا أنه كان مصابا بالبرص.","5:2":"وسبى الأراميون في إحدى غزواتهم التي أغاروا فيها على أرض إسرائيل فتاة صغيرة، صارت خادمة لزوجة نعمان.","5:3":"فقالت لمولاتها: «ياليت سيدي يمثل أمام النبي الذي في السامرة، فينال الشفاء من برصه».","5:4":"فمثل نعمان أمام الملك وأبلغه حديث الجارية الإسرائيلية.","5:5":"فقال ملك أرام: «انطلق، وسأبعث رسالة إلى ملك إسرائيل». فتوجه نعمان إلى أرض إسرائيل حاملا معه عشر وزنات من الفضة (نحو ستة وثلاثين كيلوجراما) وستة آلاف شاقل من الذهب (نحو اثنين وسبعين كيلوجراما)، وعشر حلل من الثياب،","5:6":"وسلم الرسالة إلى ملك إسرائيل، وقد ورد فيها: «وحال تسلمك لهذه الرسالة اشف نعمان خادمي الذي أرسلته إليك من برصه».","5:7":"فلما اطلع ملك إسرائيل على الرسالة مزق ثيابه وقال: «هل أنا الله حتى أميت وأحيي، فيرسل إلي هذا لكي أشفي رجلا من برصه؟ اعلموا أنه يحاول أن يجد مبررا لمحاربتنا».","5:8":"ولما سمع أليشع رجل الله أن ملك إسرائيل قد مزق ثيابه، بعث إليه يقول: «لماذا مزقت ثيابك؟ دعه يأتي إلي فيعلم أنه يوجد حقا نبي في إسرائيل».","5:9":"فأقبل نعمان بخيله ومركباته ووقف عند باب بيت أليشع،","5:10":"فوجه إليه أليشع رسولا يقول: «اذهب واغتسل سبع مرات في نهر الأردن، فتنال الشفاء».","5:11":"فغضب نعمان وانصرف قائلا: «ظننت أنه يخرج للقائي ويقف أمامي، ويدعو باسم الرب إلهه، ويمر بيده فوق موضع البرص، فأبرأ.","5:12":"أليس أبانة وفرفر نهرا دمشق أفضل من جميع مياه إسرائيل؟ ألم يكن في إمكاني الاغتسال فيها فأطهر؟» فانصرف وقد اعتراه الغيظ.","5:13":"فتقدم منه رجاله وقالوا: «ياأبانا، لو طلب النبي منك القيام بأمر عظيم، أما كنت تصنعه؟ فكم بالأحرى إن قال لك اغتسل واطهر؟»","5:14":"فنزل نعمان إلى نهر الأردن وغطس فيه سبع مرات، كما أمر رجل الله، فرجع لحمه كلحم صبي صغير، وطهر من برصه.","5:15":"فرجع إلى رجل الله مع سائر جيشه ودخل ووقف أمامه قائلا: «لقد أدركت أنه لا يوجد إله في كل الأرض إلا في إسرائيل، فأرجوك أن تقبل الآن هدية من عبدك».","5:16":"فأجاب أليشع: «حي هو الرب الذي أنا واقف في حضرته، إني لا أقبل منك هدية». فألح عليه أن يقبل منه الهدية، فأبى أليشع.","5:17":"عندئذ قال نعمان: «إذا، أرجو أن يعطى عبدك حمل بغلين من التراب، لأنه لن يقرب بعد اليوم محرقة ولا ذبيحة لآلهة أخرى، بل للرب وحده.","5:18":"ولكن ليصفح الرب عن عبدك عندما يدخل مع سيده الملك إلى بيت الإله رمون، حيث يذهب الملك مستندا على ذراعي ليسجد هناك. فعلي آنئذ أن أسجد أيضا. لهذا ليصفح الرب لعبدك عن هذا الأمر».","5:19":"فقال له أليشع: «امض بسلام».وما إن ابتعد مسافة","5:20":"حتى حدث جيحزي خادم أليشع نفسه: «سيدي امتنع عن قبول ما أحضره نعمان من هدايا. حي هو الرب لأسرعن وراءه وآخذ منه شيئا».","5:21":"فلحق جيحزي بنعمان. ولما أبصره نعمان راكضا نحوه، ترجل عن المركبة للقائه سائلا: «أللخير جئت؟»","5:22":"فأجاب: «للخير. إن سيدي قد أرسلني قائلا: إن رجلين من جبل أفرايم من بني الأنبياء جاءاه، فأرجوك أن تعطيهما وزنة من الفضة وحلتي ثياب».","5:23":"فقال نعمان: «أرجوك أن تأخذ وزنتين» وألح عليه، وصرهما في كيسين وحلتي ثياب، وأعطاهما لرجلين من رجاله، فحملاهما وانطلقا أمام جيحزي.","5:24":"وعندما وصل إلى الأكمة حيث يقيم أليشع أخذها منهما وأخفاها في البيت، وصرف الرجلين.","5:25":"ثم دخل إلى أليشع، فسأله: «من أين جئت ياجيحزي؟» فأجاب: «لم يذهب عبدك إلى أي مكان».","5:26":"فقال له: «ألا تعرف أن قلبي كان حاضرا هناك حين ترجل الرجل من مركبته للقائك؟ أهذا وقت الحصول على فضة أو أخذ ثياب وزيتون وكروم وغنم وبقر وعبيد وجوار؟","5:27":"فليحل برص نعمان بك وبنسلك إلى الأبد». فخرج من أمامه وجلده أبرص في لون الثلج.","6:1":"وقال بنو الأنبياء لأليشع: «ضاق بنا المكان الذي نحن ماكثون فيه للاجتماع بك.","6:2":"فاسمح لنا أن نذهب إلى الأردن فيقطع كل منا بعض الأخشاب لنبني مكانا أرحب نقيم فيه». فقال: «اذهبوا».","6:3":"وقال له أحدهم: «ألا تتكرم بالذهاب مع عبيدك؟» فقبل.","6:4":"ومضى معهم. وعندما وصلوا إلى نهر الأردن شرعوا في قطع الخشب.","6:5":"وفيما كان أحدهم يقطع خشبة سقط رأس فأسه الحديدي في الماء، فاستغاث بأليشع قائلا: «آه ياسيدي، إني استعرته».","6:6":"فسأله رجل الله: «أين سقط؟» فأشار إلى الموضع. فقطع أليشع عود حطب ألقاه في الماء فطفا رأس الفأس، فقال: «التقطه».","6:7":"فمد الرجل يده والتقطه.","6:8":"وحارب ملك أرام إسرائيل. وبعد التداول مع ضباطه قال: «سأعسكر في موضع كذا (لأتربص بملك إسرائيل)».","6:9":"فبعث رجل الله إلى ملك إسرائيل قائلا: «احذر الاجتياز في موضع كذا، لأن الأراميين متربصون بك فيه».","6:10":"فأرسل ملك إسرائيل مراقبيه إلى الموضع الذي أخبره عنه رجل الله وحذره منه، فتأكد من صحة النبأ. وتكررت تحذيرات أليشع للملك مرات عديدة، فكان الملك يتحفظ دائما لنفسه.","6:11":"فانزعج ملك أرام من هذا الأمر، وجمع ضباطه وسألهم: «ألا تخبرونني من منكم متآمر مع ملك إسرائيل؟»","6:12":"فأجابه واحد من ضباطه: «لا يوجد من يتآمر عليك ياسيدي الملك، ولكن النبي أليشع المقيم في إسرائيل يبلغ ملك إسرائيل حتى بالأمور التي تهمس بها في مخدع نومك».","6:13":"فقال: «اذهبوا وابحثوا لي عن مكان إقامته، فأرسل من يعتقله». فقيل له إنه في دوثان.","6:14":"فوجه ملك أرام إلى هناك جيشا كبيرا مجهزا بخيول ومركبات، وحاصر المدينة ليلا.","6:15":"فنهض خادم رجل الله مبكرا وخرج، وإذا به يجد جيشا مجهزا بخيول ومركبات يحاصر المدينة. فقال الخادم: «آه ياسيدي، ما العمل؟»","6:16":"فأجابه أليشع: «لا تخف لأن الذين معنا أكثر من الذين معهم».","6:17":"وتضرع أليشع قائلا: «يارب، افتح عينيه فيبصر». ففتح الرب عيني الخادم، وإذا به يشاهد الجبل يكتظ بخيل ومركبات نار تحيط بأليشع.","6:18":"وعندما تقدم جيش أرام نحو أليشع صلى إلى الرب قائلا: «أصب هذا الجيش بالعمى». فضربهم الرب بالعمى استجابة لدعاء أليشع.","6:19":"عندئذ قال لهم أليشع: «لقد ضللتم طريقكم فأخطأتم محاصرة المدينة المطلوبة. اتبعوني فأرشدكم إلى الرجل الذي تبحثون عنه». فقادهم إلى السامرة.","6:20":"فلما أصبحوا داخل السامرة صلى أليشع قائلا: «يارب افتح عيونهم فيبصروا». ففتح الرب عيونهم، وإذا بهم يجدون أنفسهم في وسط السامرة!","6:21":"وعندما شاهدهم ملك إسرائيل سأل أليشع: «هل أقتلهم، هل أقتلهم ياأبي؟»","6:22":"فأجابه: «لا تقتل أحدا. إنما اقتل الذين تسبيهم بسيفك وقوسك. أما هؤلاء فقدم لهم طعاما وماء فيأكلوا ويشربوا ثم ينطلقوا إلى سيدهم».","6:23":"فأقام لهم الملك مأدبة عظيمة، فأكلوا وشربوا، ثم أطلقهم، فرجعوا إلى سيدهم. وتوقفت جيوش أرام عن غزو أرض إسرائيل فترة.","6:24":"وحشد بنهدد ملك أرام، بعد زمن، كل جيشه وحاصر السامرة.","6:25":"وإذ طال الحصار، عمت المجاعة السامرة حتى صار رأس الحمار يباع بثمانين قطعة من الفضة، وأوقية زبل الحمام بخمس قطع من الفضة.","6:26":"وفيما كان ملك إسرائيل يتفقد سور المدينة استغاثت به امرأة قائلة: «أغث ياسيدي الملك».","6:27":"فقال لها: «إن لم يغثك الرب، فمن أين يمكنني أن أحصل لك على الغوث؟ أمن قمح البيدر أم من نبيذ المعصرة؟»","6:28":"ثم سألها الملك: «مالك؟» فأجابت: «لقد قالت لي هذه المرأة، هاتي ابنك فنأكله اليوم، ثم نأكل ابني في اليوم التالي.","6:29":"فسلقنا ابني وأكلناه. وعندما قلت لها في اليوم التالي: هاتي ابنك لنأكله، خبأت ابنها».","6:30":"فلما سمع الملك حديث المرأة مزق ثيابه وهو يتفقد السور، فرأى المحيطون به أنه كان يرتدي مسوحا فوق جسده.","6:31":"وقال: «ليعاقبني الرب أشد عقاب ويزد، إن لم أقطع رأس أليشع بن شافاط اليوم».","6:32":"وكان أليشع آنئذ مجتمعا في بيته مع شيوخ إسرائيل، فوجه الملك رسولا إليه يتقدمه. وقبل أن يصل الرسول قال أليشع للشيوخ: «أرأيتم كيف أن هذا القاتل قد أرسل رسولا ليقطع رأسي؟ فحالما يأتي الرسول أغلقوا الباب واتركوه موصدا في وجهه. فإن وقع خطوات سيده يتجاوب وراءه»","6:33":"وبينما هو يخاطبهم أقبل الرسول إليه، وتبعه الملك الذي قال: «إن هذا الشر قد حل بنا من عند الرب، فأي شيء أتوقع من الرب بعد؟»","7:1":"ثم قال أليشع: «اسمعوا ما يقول الرب: غدا في مثل هذا الوقت تصبح كيلة الدقيق باثني عشر جراما، وكيلتا الشعير باثني عشر جراما عند مدخل السامرة».","7:2":"فقال الجندي الذي كان الملك يتوكأ على ذراعه لرجل الله: «حتى إن فتح الرب كوى في السماء، فهل يمكن أن يحدث هذا الأمر؟» فأجاب أليشع: «سترى ذلك بعينيك، ولكنك لن تأكل منه».","7:3":"وكان هناك أربعة رجال برص عند مدخل بوابة المدينة، فقال أحدهم لرفاقه: «ما بالنا نجلس حتى نموت جوعا؟","7:4":"إن قلنا لندخل إلى المدينة، فالجوع فيها، وسنموت. وإن مكثنا هنا نموت أيضا. فهيا بنا نلجأ إلى معسكر الأراميين، فإن استحيونا عشنا، وإن قتلونا متنا».","7:5":"فانطلقوا في المساء إلى معسكر الأراميين. وعندما بلغوا أطراف المعسكر لم يجدوا هناك أحدا.","7:6":"فإن الرب قد جعل جيش أرام يسمع صلصلة مركبات، وصوت وقع حوافر خيل، وجلبة جيش كثيف، فقال أحدهم للآخر: «لابد أن ملك إسرائيل استأجر ضدنا جيوش الحثيين والمصريين لينقضوا علينا».","7:7":"ففروا هاربين عند المساء، مخلفين وراءهم خيامهم وخيولهم وحميرهم، تاركين المعسكر على حاله، وفروا ناجين بأنفسهم.","7:8":"ودخل هؤلاء البرص إحدى الخيام في أطراف المعسكر، فأكلوا وشربوا واستولوا على ما فيها من فضة وذهب وثياب، ثم طمروها. ورجعوا ودخلوا إلى خيمة أخرى واستولوا على ما فيها أيضا وطمروه.","7:9":"ثم قال بعضهم لبعض: «إننا نخطيء فيما نفعل. فاليوم يوم بشارة ونحن ساكتون، فإن انتظرنا طلوع الفجر ولم نخبر ينالنا العقاب. فلندخل المدينة ونخبر رجال قصر الملك».","7:10":"فرجعوا إلى المدينة وقالوا للبواب: «لقد دخلنا معسكر الأراميين فلم نجد فيه أحدا، ولم نسمع في أرجائه صوت إنسان. ولكننا رأينا خيلا وحميرا ما برحت معقولة في مرابضها، وخياما لا تزال منصوبة».","7:11":"فأذاع البوابون النبأ حتى بلغ قصر الملك.","7:12":"فنهض الملك ليلا وقال لضباطه: «لأخبرنكم ما صنع الأراميون! لقد أدركوا أننا نتضور جوعا، فهجروا المعسكر ليختبئوا في الحقول، حتى إذا خرجنا من المدينة ينقضون علينا ويأسروننا أحياء ويستولون على المدينة».","7:13":"فأجاب واحد من الضباط وقال: «ليأخذ بعض منا خمسة من الخيل الباقية في المدينة. فإن أصابهم شر يكونون نظير بقية الإسرائيليين المعتصمين بالمدينة، أو نظير من هلكوا من الإسرائيليين. فلنرسل ونستطلع الأمر».","7:14":"فأعدوا مركبتي خيل انطلقتا بمن فيهما من رجال أرسلهم الملك خلف الأراميين.","7:15":"فاقتفوا أثرهم إلى نهر الأردن، وإذا كل الطريق مملوءة ثيابا وأمتعة مما طرحها الأراميون عند فرارهم المفاجيء السريع. فرجع الرسل وأخبروا الملك.","7:16":"فاندفع الشعب نحو معسكر الأراميين ونهبوه، وصارت كيلة الدقيق بشاقل، وكيلتا الشعير بشاقل(اثني عشر جراما)، حسب كلام الرب.","7:17":"وعين الملك على مدخل بوابة المدينة الجندي الذي كان يتوكأ على ذراعه، فداسه الشعب في الزحام ومات عند الباب كما تنبأ أليشع في اليوم السابق عندما جاءه الملك ليقبض عليه.","7:18":"فعندما قال رجل الله للملك: «غدا في مثل هذا الوقت تكون كيلتا الشعير بشاقل وكيلة الدقيق بشاقل في مدخل بوابة السامرة».","7:19":"ولكن الجندي قال لرجل الله: «حتى إن فتح الرب كوى في السماء فهل يمكن أن يحدث هذا الأمر؟» فقال له أليشع: «سترى ذلك بعينيك ولكنك لن تأكل منه».","7:20":"فتحققت النبوءة إذ داسه الشعب عند الباب فمات.","8:1":"وقال أليشع للمرأة التي أحيا ابنها: «اذهبي أنت وعائلتك وتغربي حيث تشائين، لأن الرب سيصيب البلاد بمجاعة تدوم سبع سنوات».","8:2":"فعملت المرأة بأمر رجل الله، ورحلت هي وعائلتها إلى بلاد الفلسطينيين حيث تغربت هناك سبع سنوات.","8:3":"وفي ختام السنوات السبع رجعت المرأة من ديار الفلسطينيين، وتوجهت إلى الملك تستغيث به لاسترداد بيتها وأرضها.","8:4":"وكان الملك آنئذ يقول لجيحزي خادم رجل الله: «قص علي جميع ما أجراه أليشع من معجزات».","8:5":"وفيما هو يسرد على الملك كيف أحيا أليشع الميت أقبلت المرأة التي أحيا ابنها تستغيث بالملك لاسترداد بيتها وأرضها. فقال جيحزي: «هذه هي المرأة ياسيدي الملك، وهذا هو ابنها الذي أحياه أليشع».","8:6":"فاستخبرها الملك الأمر فحدثته به. فأمر الملك أحد موظفيه: «اعمل على استرداد كل أملاكها وكل إيراد غلات أرضها منذ أن رحلت عن البلاد إلى الآن».","8:7":"وذهب أليشع إلى دمشق. وكان بنهدد ملك أرام أيضا مريضا، فقيل له إن رجل الله جاء إلى هنا.","8:8":"فقال الملك لحزائيل: «احمل معك هدية واذهب لاستقبال رجل الله، واسأل الرب عن طريقه إن كنت سأبرأ من مرضي».","8:9":"فمضى حزائيل لاستقباله آخذا معه هدية، حمل أربعين جملا من كل خيرات دمشق. وقال لأليشع: «ابنك بنهدد ملك أرام أرسلني إليك يسأل إن كان سيبرأ من مرضه».","8:10":"فقال له أليشع: «اذهب وقل له: إنه حتما يشفى. ولكن الرب أراني أنه لابد مائت».","8:11":"وتفرس أليشع في حزائيل طويلا حتى اعترى حزائيل الخجل، وبكى رجل الله.","8:12":"فسأله حزائيل: «لماذا يبكي سيدي؟» فأجابه: «لأني عرفت ما ستنزله ببني إسرائيل من شر، فإنك ستحرق حصونهم وتقتل شبانهم وتذبح أطفالهم وتشق بطون حواملهم».","8:13":"فقال حزائيل: «كيف يمكن لمجرد كلب نظير عبدك أن يرتكب هذه الفظائع؟» فأجابه أليشع: «لقد كشف الرب لي أنك ستملك على أرام».","8:14":"فانصرف من عند أليشع ودخل إلى سيده فسأله: «ماذا قال لك أليشع؟» فأجابه: «قال لي إنك تبرأ».","8:15":"وفي صباح اليوم التالي أخذ حزائيل قطعة قماش سميكة، شبعها بالماء، وضغط بها على وجه الملك حتى أخمد أنفاسه وخلفه حزائيل على العرش.","8:16":"وفي السنة الخامسة لحكم يورام بن أخآب ملك إسرائيل، ويهوشافاط ملك يهوذا، تولى يهورام بن يهوشافاط الملك على يهوذا.","8:17":"وكان ابن اثنتين وثلاثين سنة حين ملك، وحكم ثماني سنوات في أورشليم،","8:18":"وسلك في طريق ملوك إسرائيل، على غرار بيت أخآب، لأنه كان متزوجا من بنت أخآب وارتكب الشر في عيني الرب.","8:19":"لكن الرب لم يشأ أن يفني بيت يهوذا إكراما لداود عبده، الذي وعده أنه يبقي سراجا له ولبنيه مدى الأيام.","8:20":"وفي غضون حكمه تمرد الأدوميون على يهوذا، ونصبوا عليهم ملكا.","8:21":"فاجتاز يورام نهر الأردن، بجميع مركباته إلى صعير. وعندما حاصره الأدوميون مع قادة مركباته، اقتحم خطوطهم ليلا، غير أن جيشه هربوا لاجئين إلى بيوتهم.","8:22":"وظل الأدوميون خارجين عن طاعة يهوذا إلى هذا اليوم. حينئذ تمردت لبنة أيضا.","8:23":"أما بقية أخبار يورام أليست هي مدونة في تاريخ أخبار ملوك يهوذا؟","8:24":"ومات يورام ودفن مع آبائه في مدينة داود، وخلفه ابنه أخزيا على الحكم.","8:25":"وفي السنة الثانية عشرة لحكم يورام بن أخآب ملك إسرائيل، تولى أخزيا بن يهورام ملك يهوذا.","8:26":"وكان أخزيا في الثانية والعشرين من عمره حين ملك، ودام حكمه في أورشليم سنة واحدة. واسم أمه عثليا بنت عمري ملك إسرائيل.","8:27":"وارتكب الشر في عيني الرب، على غرار بيت أخآب، لأنه كان صهرا لهم.","8:28":"وانضم أخزيا إلى يورام بن أخآب لمحاربة حزائيل ملك أرام في راموت جلعاد، فهزم الأراميون يورام.","8:29":"فتوجه يورام إلى يزرعيل ريثما يبرأ من جراحه التي أصابه بها الأراميون في راموت في أثناء المعركة مع حزائيل. وجاء أخزيا بن يهورام ملك يهوذا إلى يزرعيل ليزور يورام بن أخآب في أثناء مرضه.","9:1":"واستدعى أليشع النبي أحد الأنبياء وقال له: «تمنطق بحزامك وخذ قنينة الزيت معك، وانطلق إلى راموت جلعاد.","9:2":"وحالما تصل إلى هناك ابحث عن ياهو بن يهوشافاط بن نمشي، وانتح به في مخدع داخلي،","9:3":"وصب من قنينة الزيت على رأسه وقل له: هذا ما يقوله الرب: قد اخترتك لتكون ملكا على إسرائيل. ثم افتح الباب وأسرع بالهرب من غير توان».","9:4":"فمضى النبي الشاب إلى راموت جلعاد،","9:5":"ودخل حيث كان القادة جلوسا. فقال: «لي حديث خاص معك أيها القائد» فسأله ياهو: «مع أي قائد منا؟» فأجاب: «معك أنت أيها القائد».","9:6":"فنهض وتبعه إلى مخدع داخلي، حيث صب النبي الزيت على رأسه وقال له: «هذا ما يقوله الرب إله إسرائيل: قد اخترتك لتكون ملكا على شعب الرب إسرائيل،","9:7":"فتقضي على بيت أخآب سيدك وتنتقم لدماء عبيدي الأنبياء ودماء جميع أتقياء الرب من إيزابل،","9:8":"وبذلك تفني كل بيت أخآب، وتستأصل من بيت أخآب كل ذكر، حرا كان أم عبدا.","9:9":"وتجعل مصير بيت أخآب كمصير بيت يربعام بن نباط، وكمصير بيت بعشا بن أخيا.","9:10":"وتلتهم الكلاب إيزابل في حقل يزرعيل، ولن تجد من يدفنها». ثم فتح الباب ولاذ بالفرار.","9:11":"وعندما رجع ياهو إلى حيث يجتمع رجال سيده سئل: «أخير؟ لماذا جاءك هذا المجنون؟» فأجابهم: «أنتم تعرفون الرجل وما يهذي به».","9:12":"فقالوا: «هذا ليس صحيحا. أخبرنا الصدق». فقال: «إليكم ما خاطبني به: قال: هذا ما صدر عن الرب: قد اخترتك لتكون ملكا على إسرائيل».","9:13":"فبادر كل واحد منهم وفرش ثوبه فوق درجات السلم حيث كان يقف، ونفخوا بالأبواق قائلين: «قد ملك ياهو».","9:14":"وهكذا تمرد ياهو بن يهوشافاط بن نمشي على يورام. وكان يورام مع سائر جيش إسرائيل يدافعون عن راموت جلعاد ضد هجمات حزائيل ملك أرام.","9:15":"وكان يهورام الملك قد لجأ إلى يزرعيل ريثما يبرأ من الجراح التي أصابه بها الأراميون في حربه مع حزائيل ملك أرام. فقال ياهو: «إن كانت هذه رغبتكم فلا تدعوا أحدا ينسل من المدينة ليذيع الخبر في يزرعيل».","9:16":"ثم امتطى مركبته وانطلق إلى يزرعيل حيث كان يورام مضطجعا هناك، وقد جاء أخزيا ملك يهوذا ليزوره.","9:17":"وكان الرقيب قائما على برج يزرعيل، فشاهد جماعة ياهو مقبلين، فقال للملك: «إني أرى قوما قادمين». فأمره يهورام: «أرسل فارسا للقائهم، فيسألهم: أللخير قدومهم؟»","9:18":"فا ندفع فارس للقائهم قائلا: «إن الملك يسأل: أللخير قدومكم؟» فأجابه ياهو: «ما شأنك بالخير؟ در وانضم إلي». فقال الرقيب للملك: «قد وصل الرسول إليهم ولم يرجع».","9:19":"فأرسل فارسا آخر. فلما التقاهم قال: «إن الملك يسأل: أللخير قدومكم؟» فأجابه ياهو: «ما شأنك بالخير؟ در وانضم إلي».","9:20":"فقال الرقيب للملك: «قد وصل الرسول إليهم ولم يرجع. وقيادة المركبة شبيهة بقيادة ياهو بن نمشي، لأنه يقودها كرجل مجنون».","9:21":"فأمر يهورام بتجهيز مركبته، وخرج يصاحبه أخزيا ملك يهوذا، كل في مركبته، للقاء ياهو. فصادفاه عند حقل نابوت اليززعيلي","9:22":"فلما رأى يهورام ياهو سأله: «أللخير قدومك؟» فأجابه ياهو: «أي خير مادام فجور أمك إيزابل وسحرها متفشيين؟»","9:23":"فأمسك يهورام زمام المركبة وأطلق العنان لخيوله هاربا هاتفا بأخزيا: «خيانة ياأخزيا!»","9:24":"فأطلق ياهو سهما على يهورام اخترق ظهره ونفذ من قلبه، فأرداه قتيلا في مركبته،","9:25":"وقال لبدقر قائد مركبته: «ارفعه واطرحه في حقل نابوت اليزرعيلي، وتذكر كيف أن الرب، حين كنت أنا وأنت راكبين خلف أبيه أخآب قد قضى عليه بهذا العقاب،","9:26":"فالرب يقول: لقد رأيت أمسا دم نابوت ودماء أبنائه، لهذا لابد أن أعاقبك في هذا الحقل. فالآن ارفعه واطرحه في الحقل حسب قول الرب».","9:27":"وعندما رأى أخزيا ملك يهوذا هذا، فر هاربا في الطريق المفضية إلى بيت البستان، فتعقبه ياهو هاتفا: «اقتلوه». فأصابوه بجراح مميتة وهو في مركبته عند عقبة جور القريبة من يبلعام، ولكنه تابع هربه إلى مجدو حيث مات هناك.","9:28":"فنقله رجاله في مركبته إلى أورشليم حيث دفنوه في قبره مع آبائه في مدينة داود.","9:29":"وكان أخزيا قد ملك على يهوذا في السنة الحادية عشرة من حكم يورام بن أخآب على إسرائيل.","9:30":"وتوجه ياهو إلى يزرعيل. فلما علمت إيزابل بذلك كحلت عينيها وزينت شعرها وأطلت من الكوة.","9:31":"وعندما اجتاز ياهو عتبة باب ساحة القصر قالت: «أجئت مسالما يازمري ياقاتل سيده؟»","9:32":"فرفع وجهه إليها وصاح: «من هنا معي؟» فأشرف عليه اثنان أو ثلاثة من الخصيان.","9:33":"فقال: «اطرحوها». فألقوا بها من الكوة فتناثر بعض دمها على الجدار وعلى الخيل التي داستها بحوافرها.","9:34":"ودخل بعد ذلك إلى القصر حيث أكل وشرب ثم قال: «اذهبوا وافتقدوا هذه المرأة الملعونة وادفنوها، لأنها بنت ملك».","9:35":"وعندما خرجوا ليدفنوها لم يجدوا من أشلائها سوى الجمجمة والرجلين وكفي اليدين،","9:36":"فرجعوا وأخبروه، فقال: «هذا إتمام لقضاء الرب الذي نطق به على لسان إيليا التشبي قائلا: إن الكلاب ستلتهم لحم إيزابل في حقل يزرعيل.","9:37":"وتصبح جثة إيزابل كالزبل على وجه حقل يزرعيل بحيث لا يتعرف عليها أحد فيقول: هذه إيزابل».","10:1":"وكان لأخآب سبعون ابنا يقيمون في السامرة، فكتب ياهو رسائل بعث بها إلى شيوخ مدينة يزرعيل وإلى الأوصياء على أبناء أخآب قائلا:","10:2":"«من حيث أن أبناء سيدكم لديكم، ومن حيث أنكم تمتلكون مركبات وخيلا وتعتصمون بمدينة محصنة، وعندكم سلاح، فعند تلقيكم هذه الرسالة","10:3":"اختاروا الأفضل من أبناء سيدكم ونصبوه ملكا على عرش أبيه، ودافعوا عن بيت مولاكم».","10:4":"فاعتراهم خوف عظيم وقالوا: «ها ملكان قد عجزا عن صده، فكيف يمكننا نحن أن نواجهه؟»","10:5":"فأجاب مدبر القصر ومحافظ المدينة والشيوخ والأوصياء ياهو قائلين: «نحن عبيدك، وسنفعل كل ما تأمر به. لن يملك علينا سواك. واصنع ما يروق لك».","10:6":"فبعث إليهم برسالة ثانية قائلا: «إن كنتم حقا من أنصاري، وتأتمرون بأمري، فاقطعوا رؤوس أبناء سيدكم من الرجال وأحضروها إلي في يزرعيل، في نحو هذا الوقت في يوم الغد». وكان أبناء الملك سبعين رجلا يعيشون في رعاية أشراف المدينة الذين تعهدوهم بالتربية.","10:7":"فلما بلغتهم رسالة ياهو قبضوا على الأمراء وقتلوا سبعين رجلا ووضعوا رؤوسهم في سلال وأرسلوها إليه في يزرعيل.","10:8":"فجاء رسول وأخبر ياهو قائلا: «قد أحضروا رؤوس الأمراء» فقال: «اجعلوها كومتين في مدخل بوابة المدينة إلى الصباح».","10:9":"وفي صباح اليوم التالي خرج وقال للشعب المتجمهر: «أنتم أبرياء،، فها أنا قد تمردت على سيدي وقتلته، ولكن من قتل كل هؤلاء؟","10:10":"فاعلموا الآن أنه لن تسقط كلمة واحدة مما قضى به الرب على بيت أخآب، وقد نفذ الرب ما نطق به على لسان عبده إيليا».","10:11":"وقضى ياهو على البقية الباقية من نسل أخآب في يزرعيل، وعلى كل عظمائه وأصدقائه وكهنته، فلم يفلت له حي.","10:12":"ثم توجه من هناك نحو السامرة. ولما وصل إلى جوار بيت عقد الرعاة في الطريق،","10:13":"صادف ياهو إخوة أخزيا ملك يهوذا، فسألهم: «من أنتم؟» فأجابوا: «نحن إخوة أخزيا، ونحن قادمون لزيارة أبناء الملك والملكة إيزابل».","10:14":"فقال: «اقبضوا عليهم أحياء». فقبضوا عليهم أحياء وقتلوهم جميعا عند بئر بيت عقد، وعددهم اثنان وأربعون رجلا.","10:15":"ثم انطلق من هناك فالتقى يهوناداب بن ركاب، الذي كان قادما لمقابلته، فحياه ياهو ثم سأله: «هل قلبك مخلص لقلبي مثل إخلاص قلبي لقلبك؟» فأجابه يهوناداب: «نعم». فقال ياهو: «إذن هات يدك». فمد إليه يده فأصعده معه إلى المركبة،","10:16":"وقال: «تعال معي لترى مدى غيرتي للرب»، وهكذا أركبه معه في المركبة.","10:17":"وعندما وصل ياهو إلى السامرة أهلك جميع من بقي من ذرية أخآب، فأفناهم بموجب قضاء الرب الذي كلم به إيليا.","10:18":"ثم جمع ياهو كل الشعب وقال لهم: «لقد عبد أخآب البعل عبادة طفيفة، أما أنا فأغالي في عبادته.","10:19":"فادعوا إلي الآن جميع أنبياء البعل وكل كهنته والمتعبدين له. لا يتخلف منهم أحد، لأنني عازم أن أقرب ذبيحة عظيمة للبعل. وكل من يتخلف عن الحضور يموت». وكان ذلك مكيدة منه لكي يستأصل عبدة البعل.","10:20":"وقال ياهو: «أقيموا محفلا مقدسا للبعل». فنادوا به.","10:21":"واستدعى ياهو جميع عبدة البعل من كل إسرائيل، فلم يتخلف أحد منهم، ودخلوا معبد البعل فامتلأ بهم المكان،","10:22":"فقال للمشرف على الملابس: «وزع ملابس على كل عبدة البعل». فأخرجها ووزعها عليهم.","10:23":"ثم دخل ياهو ويهوناداب بن ركاب إلى معبد البعل، وقال لهم: «فتشوا إن كان قد اندس بينكم واحد من عبيد الرب، إذ لا يجب أن يكون هنا سوى عبدة البعل فقط».","10:24":"وهكذا دخلوا ليقربوا ذبائح ومحرقات. وكان ياهو قد رصد كمينا من ثمانين رجلا خارج المعبد وقال لهم: «إن أفلت منكم أحد من عبدة البعل تكون أنفسكم عوضا عنه».","10:25":"وعندما فرغ ياهو من تقريب المحرقة، قال للحراس والضباط: «ادخلوا وأهلكوهم! لا يفلت منهم أحد». فأبادوهم بحد السيف، وطرحوا جثثهم. ثم توجهوا نحو المحراب الداخلي لمعبد البعل،","10:26":"فأخرجوا التماثيل وأحرقوها،","10:27":"وحطموا تمثال البعل، وهدموا المعبد وحولوه إلى مزبلة إلى هذا اليوم.","10:28":"واستأصل ياهو عبادة البعل من إسرائيل.","10:29":"ولكنه لم يحد عن خطايا يربعام التي استغوى بها الإسرائيليين وجعلهم يخطئون، إذ أبقى على عجول الذهب التي في بيت إيل وفي دان.","10:30":"وقال الرب لياهو: «من حيث أنك قد أحسنت بتنفيذ ما هو صالح في عيني، وأجريت على بيت أخآب ما أضمرته في قلبي، فإن أبناءك يتربعون على عرش إسرائيل إلى الجيل الرابع».","10:31":"ولكن ياهو لم يحرص على السلوك في شريعة الرب إله إسرائيل من كل قلبه، إذ واظب على ارتكاب خطايا يربعام التي استغوى بها الإسرائيليين وجعلهم يخطئون.","10:32":"وفي تلك الأيام بدأ الرب يخفض من مساحة أرض إسرائيل، فاستولى حزائيل على أجزاء كبيرة من مناطقهم.","10:33":"ابتداء من شرقي نهر الأردن، بما في ذلك أرض جلعاد، أرض الجاديين والرأوبينيين، والمنسيين، من عروعير القائمة على وادي أرنون وجلعاد وباشان.","10:34":"أما بقية أخبار ياهو وكل ما عمله أليست هي مدونة في كتاب أخبار ملوك إسرائيل؟","10:35":"ومات ياهو ودفن في السامرة وخلفه ابنه يهوأحاز.","10:36":"ودام ملك ياهو على إسرائيل في السامرة ثمانيا وعشرين سنة.","11:1":"وعندما بلغ عثليا أم أخزيا أن ابنها قد قتل عمدت إلى إبادة النسل الملكي.","11:2":"ولم ينج من الموت من بين جميع أبناء الملك الذين قتلتهم جدتهم عثليا سوى يوآش بن أخزيا الذي اختطفته عمته يهوشبع بنت الملك يورام مع مرضعته من مخدع النوم وخبأته عن عيني عثليا.","11:3":"وظل يهوآش مختبئا مع مرضعته في بيت الرب مدة ست سنوات، كانت عثليا في أثنائها متربعة على عرش يهوذا.","11:4":"وفي السنة السابعة استدعى يهوياداع رؤساء المئات من ضباط القصر وحرس الملكة، وأدخلهم إلى بيت الرب، فقطع معهم عهدا واستحلفهم على الكتمان في بيت الرب. ثم أراهم ابن الملك.","11:5":"وأمرهم قائلا: «إليكم ما تفعلونه. ليقم ثلث الحراس المتولين الخدمة يوم السبت بحراسة القصر.","11:6":"وليحرس الثلث الثاني باب سور، أما الثلث الثالث فليتول حراسة الباب وراء الحرس الملكي. وهكذا تقومون بالدفاع عن القصر وصد كل هجوم.","11:7":"وعلى الفرقتين المعفاتين من الواجبات في يوم السبت القيام بحراسة بيت الرب وحماية الملك.","11:8":"فتحيطون بالملك وأنتم مدججون بالسلاح. واقتلوا كل من يحاول أن يخترق الصفوف إليه، ولازموا الملك في دخوله وخروجه».","11:9":"فنفذ رؤساء المئات أوامر يهوياداع الكاهن، وأحضر كل منهم رجاله سواء كانوا معفين من خدمة السبت أو المكلفين بها، إلى يهوياداع الكاهن.","11:10":"فسلم الكاهن رؤساء المئات حراب الملك داود وأتراسه المحفوظة في الهيكل،","11:11":"ووقف الحراس مدججين بالسلاح محيطين بمخبإ الملك وحول الهيكل والمذبح.","11:12":"وأخرج يهوياداع ابن الملك وتوجه، وأعطاه نسخة من شهادة العهد، فنصبوه ملكا ومسحوه وصفقوا هاتفين: «ليحي الملك».","11:13":"وحين سمعت عثليا هتاف الحراس والشعب، اندست بين الشعب واندفعت إلى بيت الرب،","11:14":"فشاهدت الملك منتصبا على المنبر وفقا للتقليد في تتويج الملوك، ورؤساء الحراس ونافخو الأبواق يحيطون بالملك، وقد امتزجت هتافات فرح الشعب بدوي نفخ الأبواق، فشقت عثليا ثيابها صارخة: «خيانة! خيانة!»","11:15":"فأمر يهوياداع الكاهن رؤساء المئات من قادة الجيش قائلا: «خذوها إلى خارج الصفوف واقتلوا بالسيف كل من يحاول إنقاذها». لأن الكاهن أمر أن لا تقتل داخل بيت الرب.","11:16":"فقبضوا عليها وجروها إلى المدخل الذي تعبر منه الخيل إلى ساحة القصر حيث قتلت هناك.","11:17":"وأبرم يهوياداع عهدا بين الرب وبين الملك والشعب، حتى يكونوا شعبا للرب، كما أبرم عهدا أيضا بين الملك والشعب.","11:18":"ثم توجه جميع شعب الأرض إلى معبد البعل، وهدموا مذابحه وحطموا تماثيله، وقتلوا متان كاهن البعل أمام المذبح. وأقام الكاهن حراسا على بيت الرب.","11:19":"واصطحب معه رؤساء المئات والضباط والحرس وسائر الشعب الحاضر هناك، وواكبوا الملك من بيت الرب عبر طريق السعاة إلى القصر حيث جلس على عرش الملك.","11:20":"وعم الفرح الشعب، وغمرت الطمأنينة المدينة بعد مقتل عثليا بالسيف عند القصر.","11:21":"وكان يهوآش في السابعة من عمره عندما اعتلى العرش.","12:1":"في السنة السابعة من حكم ياهو تولى يهوآش عرش يهوذا، فملك أربعين سنة في أورشليم. واسم أمه ظبية من بئر سبع.","12:2":"وسلك يهوآش باستقامة في عيني الرب طوال الأيام التي أشرف فيها يهوياداع الكاهن على توجيهه،","12:3":"غير أنه لم يهدم المرتفعات، بل ظل الشعب يذبح ويوقد عليها.","12:4":"وقال يهوآش للكهنة: «اجمعوا الفضة المخصصة للتقدمات في هيكل الرب، والفضة التي جبيت من الإحصاء، وفضة النذور، والفضة المقدمة بصورة طوعية لهيكل الرب.","12:5":"وليتسلم كل كاهن الفضة من أمين المال لترميم كل ما تهدم من هيكل الرب».","12:6":"ولكن الهيكل ظل من غير ترميم أو إصلاح حتى العام الثالث والعشرين من حكم يهوآش.","12:7":"فاستدعى الملك يهوآش يهوياداع رئيس الكهنة وسائر الكهنة وقال لهم: «لماذا لم ترمموا ما تهدم في هيكل الرب؟ والآن لا تأخذوا فضة من أمين المال، بل لتظل مخصصة لترميم ما تهدم من هيكل الرب».","12:8":"فوافق الكهنة أن لا يأخذوا فضة من الشعب لحاجتهم، وأن لا يقوموا بترميم هيكل الرب بأنفسهم.","12:9":"وأحضر يهوياداع الكاهن صندوقا ثقب في غطائه ثقبا، ووضعه إلى يمين المذبح عند مدخل هيكل الرب، فكان الكهنة حراس المدخل يضعون فيه كل الفضة المقدمة لهيكل الرب.","12:10":"وكان كلما امتلأ الصندوق بالفضة يحضر كاتب الملك ورئيس الكهنة فيحصيانها ويصرانها.","12:11":"ويسلمان الفضة المحصاة إلى النظار الموكلين بالإشراف على أعمال هيكل الرب فيدفعونها للنجارين والبنائين العاملين في ترميم هيكل الرب،","12:12":"ولبنائي الجدران ونحاتي الحجارة، وكذلك لشراء الأخشاب والحجارة المنحوتة، لترميم كل ما تهدم من هيكل الرب، ولغيرها من نفقات الترميم.","12:13":"إلا أن الأموال لم تستخدم في صنع طسوس فضة لهيكل الرب، ولا مقصات، ولا مناضح، ولا أبواق وآنية ذهب وفضة.","12:14":"بل كانوا يسلمون الفضة كلها للنظار المشرفين على العمل، فيقوم هؤلاء بترميم هيكل الرب.","12:15":"ولم يطالب المشرفون على سير العمل بتقديم حساب عما أنفقوه على العاملين في إصلاح الهيكل، لأن هؤلاء النظار كانوا يعملون بأمانة.","12:16":"أما الفضة التي قدمها الشعب من أجل ذبيحة الإثم وذبيحة الخطيئة فلم تحسب مع الفضة الداخلة إلى صندوق الهيكل، بل أعطيت للكهنة.","12:17":"وزحف في نحو ذلك الوقت حزائيل ملك أرام وهاجم جت واستولى عليها، ثم توجه لمهاجمة أورشليم وإسقاطها.","12:18":"فجمع يهوآش ملك يهوذا كل الأقداس التي خصصها يهوشافاط ويهورام وأخزيا آباؤه ملوك يهوذا، وما خصصه هو من أقداس، وكل الذهب الموجود في خزائن هيكل الرب وقصر الملك، وأرسلها إلى حزائيل ملك أرام. فرجع عن مهاجمة أورشليم.","12:19":"أما بقية أخبار يهوآش وأعماله أليست هي مدونة في كتاب أخبار ملوك يهوذا؟","12:20":"وتمرد عليه بعض ضباطه فقتلوه في بيت القلعة عند الطريق المفضي إلى سلى.","12:21":"إذ اغتاله يوزاكار بن شمعة ويهوزاباد بن شومير، فدفنوه مع آبائه في مدينة داود. وخلفه ابنه أمصيا على العرش.","13:1":"وفي السنة الثالثة والعشرين من حكم يوآش بن أخزيا تولى يهوأحاز بن ياهو عرش إسرائيل، ودام ملكه في السامرة سبع عشرة سنة.","13:2":"وارتكب الشر في عيني الرب، وزاغ وراء خطايا يربعام بن نباط الذي استغوى بني إسرائيل فأخطأوا، ولم يحد عنها.","13:3":"فاحتدم غضب الرب على إسرائيل، وسلط عليهم حزائيل ملك أرام، ومن بعده ابنه بنهدد طوال حياته.","13:4":"فتضرع يهوأحاز إلى الرب فاستجاب له، لأنه رأى ما يعانيه شعب إسرائيل من مشقة من جراء مضايقات ملك أرام.","13:5":"فأقام الرب من بينهم منقذا خلصهم من نير الأراميين فسكن الإسرائيليون في منازلهم بطمأنينة كعهدهم في الأيام الغابرة.","13:6":"ولكنهم لم يحيدوا عن خطايا بيت يربعام التي استغوى بها بني إسرائيل فأخطأوا، بل أمعنوا فيها. وظل صنم عشتاروث قائما في السامرة.","13:7":"ولم يكن قد بقي من جيش يهوأحاز سوى خمسين فارسا، وعشر مركبات، وعشرة آلاف رجل من المشاة، لأن ملك أرام أفناهم وداس عليهم كما يداس على التراب.","13:8":"أما بقية أخبار يهوأحاز وأعماله وطغيانه، أليست هي مدونة في كتاب أخبار أيام ملوك يهوذا؟","13:9":"ثم مات يهوأحاز فدفنوه في السامرة، وخلفه ابنه يوآش على الملك.","13:10":"وفي السنة السابعة والثلاثين من حكم يوآش ملك يهوذا، تولى يهوآش بن يهوأحاز عرش إسرائيل، ودام حكمه في السامرة ست عشرة سنة.","13:11":"وارتكب الشر في عيني الرب، وأمعن في اقتراف جميع خطايا يربعام بن نباط التي استغوى بها بني إسرائيل فأخطأوا،","13:12":"أما بقية أخبار يوآش وكل ما قام به من أعمال، وكيف حارب أمصيا ملك يهوذا أليست هي مدونة في كتاب أخبار أيام ملوك إسرائيل؟","13:13":"ثم مات يوآش، وخلفه يربعام على عرشه. ودفن يوآش في السامرة مع ملوك إسرائيل.","13:14":"وعندما مرض أليشع وأشرف على الموت زاره يوآش ملك إسرائيل، وأكب على وجهه باكيا قائلا: «ياأبي، ياأبي، يامركبات إسرائيل وفرسانها».","13:15":"فقال له أليشع: «تناول قوسا وسهاما». فأخذ لنفسه قوسا وسهاما.","13:16":"ثم قال للملك: «وتر القوس» فوتر القوس، ثم وضع أليشع يده على يدي الملك.","13:17":"وقال: «افتح الكوة الشرقية». ففتحها، فقال أليشع: «ارم السهم». فأطلقه فقال أليشع: «هذا سهم خلاص للرب، سهم انتصار على أرام، فها أنت ستقضي على أرام في أفيق وتفنيهم».","13:18":"ثم قال أليشع: «خذ السهام». فأخذها. فقال أليشع للملك: «اضرب على الأرض» فضرب على الأرض ثلاث مرات وتوقف،","13:19":"فسخط عليه أليشع وقال: «لو ضربت خمس أو ست مرات لظللت تلحق الهزيمة بأرام حتى تبيدهم، ولكنك الآن لن تنتصر عليهم سوى ثلاث مرات».","13:20":"ومات أليشع فدفنوه. وحدث أن غزاة الموآبيين أغاروا على أرض إسرائيل عند مطلع السنة الجديدة،","13:21":"فيما كان قوم يقومون بدفن رجل ميت. فما إن رأوا الغزاة قادمين حتى طرحوا الجثمان في قبر أليشع، وما كاد جثمان الميت يمس عظام أليشع حتى ارتدت إليه الحياة، فعاش ونهض على رجليه.","13:22":"أما حزائيل ملك أرام فاستمر في مضايقة إسرائيل طوال أيام يهوأحاز،","13:23":"فأشفق الرب عليهم ورحمهم، وأبدى اهتمامه بهم إكراما لعهده مع إبراهيم وإسحق ويعقوب، ولم يشأ أن يبيدهم أو ينبذهم حتى تلك اللحظة.","13:24":"ثم مات حزائيل ملك أرام وخلفه ابنه بنهدد.","13:25":"فاسترجع يهوآش بن يهوأحاز من يد بنهدد بن حزائيل المدن التي استولى عليها من أبيه يهوأحاز في الحرب، وهزمه يوآش ثلاث مرات، تمكن خلالها من استرداد مدن إسرائيل.","14:1":"وفي السنة الثانية من حكم يوآش بن يوأحاز ملك إسرائيل، تولى أمصيا بن يوآش الملك على يهوذا","14:2":"وكان في الخامسة والعشرين حين ملك، ودام حكمه تسعا وعشرين سنة في أورشليم. واسم أمه يهوعدان من أورشليم.","14:3":"وصنع كل ما هو صالح في عيني الرب، على غرار أبيه يوآش، ولكنه لم يبلغ صلاح جده الأكبر داود.","14:4":"إذ لم يهدم المرتفعات، بل ظل الشعب يذبحون عليها ويوقدون.","14:5":"وعندما استتب الملك في يده قتل رجاله الذين اغتالوا أباه الملك.","14:6":"ولكنه لم يقتص من أبنائهم عملا بما هو وارد في كتاب شريعة موسى، حيث أمر الرب قائلا: «لا يقتل الآباء بذنب البنين ولا يقتل البنون بذنب الآباء، إنما يقتل كل إنسان بما جنت يداه».","14:7":"وهو الذي قتل عشرة آلاف من الأدوميين في وادي الملح، واستولى على سالع بالحرب، ودعا اسمها يقتئيل إلى هذا اليوم.","14:8":"وبعث أمصيا رسلا إلى يهوآش بن يهوأحاز بن ياهو ملك إسرائيل قائلا: «تعال نتواجه للقتال».","14:9":"فأجابه يهوآش: «أرسل العوسج النابت في لبنان إلى الأرز في لبنان يقول: زوج ابنتك من ابني. فمر حيوان بري كان هناك، فوطيء العوسج!","14:10":"لقد هزمت الأدوميين فانتابك الغرور، ولكن خير لك أن تمكث في قصرك وتتمتع بمجد انتصارك. فلماذا تسعى إلى الشر فتجلب الدمار عليك وعلى يهوذا؟»","14:11":"فلم يصغ أمصيا له، فحشد يهوآش ملك إسرائيل جيوشه وتواجه مع أمصيا ملك يهوذا في بيت شمس التابعة لمملكة يهوذا.","14:12":"فانهزم يهوذا أمام جيش إسرائيل وهربوا إلى منازلهم،","14:13":"ووقع أمصيا في أسر يهوآش في بيت شمس. وتوجه بجيشه نحو أورشليم وهدم سورها من باب أفرايم إلى باب الزاوية على امتداد أربع مئة ذراع (نحو مئتي متر)","14:14":"واستولى على كل الذهب والفضة، وجميع الآنية الموجودة في هيكل الرب وفي قصر الملك، وأخذ رهائن ثم عاد إلى السامرة.","14:15":"أما بقية أخبار يهوآش وما قام به من أعمال وكيف حارب أمصيا ملك يهوذا أليست هي مدونة في كتاب أخبار أيام ملوك إسرائيل؟","14:16":"ثم مات يهوآش ودفن في السامرة مع ملوك إسرائيل، وخلفه ابنه يربعام.","14:17":"وعاش أمصيا بن يوآش ملك يهوذا خمس عشرة سنة بعد وفاة يهوآش بن يهوأحاز ملك إسرائيل.","14:18":"أما بقية أخبار أمصيا أليست هي مدونة في كتاب أخبار أيام ملوك يهوذا؟","14:19":"وثارت عليه فتنة في أورشليم، فلجأ إلى لخيش، ولكنهم أرسلوا من تعقبوه إلى هناك واغتالوه،","14:20":"ثم نقلوه على الخيل إلى أورشليم حيث دفن مع آبائه في مدينة داود.","14:21":"ونصب كل شعب يهوذا ابنه عزريا ملكا، وله من العمر ست عشرة سنة، فخلف أباه أمصيا على العرش.","14:22":"وهو الذي استرد أيلة ليهوذا ورممها عقب وفاة والده الملك أمصيا.","14:23":"وفي السنة الخامسة عشرة من حكم أمصيا بن يوآش ملك يهوذا، تولى يربعام بن يوآش عرش إسرائيل في السامرة إحدى وأربعين سنة.","14:24":"وارتكب الشر في عيني الرب، ولم يعدل عن أي من خطايا يربعام بن نباط التي استغوى بها الإسرائيليين فأخطأوا.","14:25":"وهو الذي استرجع لإسرائيل أراضيها الممتدة من حماة إلى البحر الميت، تحقيقا لكلام الرب الذي نطق به على لسان عبده يونان بن أمتاي النبي من أهل جت حافر،","14:26":"لأن الرب رأى ما يعانيه الإسرائيليون من عبيد وأحرار من ضيق أليم مرير. ولم يكن لهم من معين.","14:27":"وإذ لم يكن الرب قد قضى بمحو اسم إسرائيل من تحت السماء، أنقذهم على يد يربعام بن يوآش.","14:28":"أما بقية أخبار يربعام وكل منجزاته وأعماله وكيف حارب واسترجع لإسرائيل كلا من دمشق وحماة التي استولى عليها يهوذا أليست هي مدونة في كتاب أخبار أيام ملوك إسرائيل؟","14:29":"ثم مات يربعام ودفن مع آبائه ملوك إسرائيل، وخلفه ابنه زكريا على الملك.","15:1":"وفي السنة السابعة والعشرين من حكم يربعام ملك إسرائيل، تولى عزريا بن أمصيا عرش يهوذا.","15:2":"وكان عمره ست عشرة سنة حين ملك، ودام حكمه في أورشليم اثنتين وخمسين سنة، واسم أمه يكليا من أورشليم.","15:3":"وصنع ما هو صالح في عيني الرب على غرار أبيه أمصيا،","15:4":"غير أنه لم يهدم المرتفعات. وظل الشعب يقربون عليها ويوقدون.","15:5":"وابتلى الرب عزريا بداء البرص إلى يوم وفاته، مما أرغمه على الإقامة في بيت منعزل، فتولى ابنه يوثام حكم الشعب بالنيابة عنه.","15:6":"أما بقية أخبار عزريا ومنجزاته أليست هي مدونة في كتاب أخبار أيام ملوك يهوذا؟","15:7":"ثم مات عزريا ودفن مع آبائه في مدينة داود، وخلفه ابنه يوثام.","15:8":"وفي السنة الثامنة والثلاثين لحكم عزريا ملك يهوذا، اعتلى زكريا بن يربعام عرش إسرائيل في السامرة مدة ستة أشهر.","15:9":"وارتكب الشر في عيني الرب على غرار أبائه ولم يعدل عن أي من خطايا يربعام بن نباط التي استغوى بها الإسرائيليين فأخطأوا.","15:10":"وتمرد عليه شلوم بن يابيش واغتاله أمام الشعب واغتصب منه الملك.","15:11":"أما بقية أخبار زكريا فهي مدونة في كتاب أخبار أيام ملوك إسرائيل،","15:12":"وكان ذلك تحقيقا لكلام الرب الذي وعد به ياهو قائلا: «إن من ذريتك حتى الجيل الرابع يكونون ملوكا على إسرائيل».","15:13":"وملك شلوم بن يابيش في السنة التاسعة والثلاثين من حكم عزيا (عزريا) ملك يهوذا، ودام ملكه مدة شهر واحد في السامرة.","15:14":"وذهب منحيم بن جادي من ترصة إلى السامرة واغتال شلوم بن يابيش، وخلفه على كرسي المملكة.","15:15":"أما بقية أخبار شلوم وتمرده فهي مدونة في كتاب أخبار أيام ملوك إسرائيل.","15:16":"بعد ذلك هاجم منحيم تفصح وضواحيها، وهدم ما فيها حتى حدود ترصة لأن أهلها أبوا أن يفتحوا بواباتها له، وشق بطون جميع حواملها.","15:17":"وفي السنة التاسعة والثلاثين لحكم عزريا ملك يهوذا، اعتلى منحيم بن جادي عرش إسرائيل في السامرة لمدة عشر سنين،","15:18":"وارتكب الشر في عيني الرب على غرار خطايا يربعام بن نباط التي استغوى بها الإسرائيليين فأخطأوا طوال أيامه.","15:19":"وأغار فول ملك أشور على البلاد، فاسترضاه منحيم بألف وزنة (نحو ثلاثة آلاف وست مئة كيلوجرام) من الفضة ليوآزره في تثبيته على العرش.","15:20":"وجبى منحيم خمسين شاقل (نحو ست مئة جراما) من الفضة من كل رجل من أثرياء الإسرائيليين ليدفعها لملك أشور، فرجع ملك أشور ولم يحتل الأرض.","15:21":"أما بقية أخبار منحيم ومنجزاته أليست هي مدونة في كتاب أخبار أيام ملوك إسرائيل؟","15:22":"ثم مات منحيم ودفن مع آبائه، وخلفه ابنه فقحيا على الملك.","15:23":"وفي السنة الخمسين لحكم عزريا ملك يهوذا، اعتلى فقحيا بن منحيم عرش إسرائيل لمدة سنتين،","15:24":"وارتكب الشر في عيني الرب على غرار خطايا يربعام بن نباط التي استغوى بها الإسرائيليين،","15:25":"فثار عليه فقح بن رمليا، أحد قواده مع خمسين جنديا من الجلعاديين، واغتاله في السامرة في عقر قصره، كما اغتال معه أرجوب وأرية، وخلفه على الملك.","15:26":"أما بقية أعمال فقحيا ومنجزاته، فهي مدونة في كتاب أخبار أيام ملوك إسرائيل.","15:27":"وفي السنة الثانية والخمسين لحكم عزريا ملك يهوذا، اعتلى فقح بن رمليا عرش إسرائيل في السامرة لمدة عشرين سنة.","15:28":"وارتكب الشر في عيني الرب على غرار خطايا يربعام بن نباط التي استغوى بها الإسرائيليين فأخطأوا.","15:29":"وفي أيامه هاجم تغلث فلاسر ملك أشور البلاد، واستولى على مدن عيون، وآبل بيت معكة، ويانوح، وقادش، وحاصور، وجلعاد والجليل، وكل أرض نفتالي وسبى أهلها إلى أشور.","15:30":"ثم تمرد هوشع بن أيلة على فقح بن رمليا واغتاله، وخلفه على الملك في السنة العشرين ليوثام بن عزيا (عزريا).","15:31":"أما بقية أخبار فقح فهي مدونة في كتاب أخبار أيام ملوك إسرائيل.","15:32":"وفي السنة الثانية لحكم فقح بن رمليا ملك إسرائيل، اعتلى يوثام بن عزيا عرش يهوذا،","15:33":"وكان له من العمر خمس وعشرون سنة حين ملك، ودام حكمه في أورشليم ست عشرة سنة، واسم أمه يروشا ابنة صادوق.","15:34":"وصنع كل ما هو صالح في عيني الرب، سالكا في نهج أبيه عزيا.","15:35":"ولكنه لم يهدم المرتفعات، وظل الشعب يقربون عليها ويوقدون. وهو الذي بنى الباب الأعلى لهيكل الرب.","15:36":"أما بقية أخبار يوثام ومنجزاته أليست هي مدونة في كتاب أخبار أيام ملوك يهوذا؟","15:37":"وفي ذلك الوقت شرع الرب يرسل على يهوذا رصين ملك أرام وفقح بن رمليا.","15:38":"ومات يوثام ودفن مع آبائه في مدينة أبيه داود،وخلفه آحاز على الملك.","16:1":"وفي السنة السابعة عشرة من حكم فقح بن رمليا، اعتلى آحاز بن يوثام عرش يهوذا","16:2":"وكان له من العمر عشرون سنة حين ملك. ودام حكمه ست عشرة سنة في أورشليم، وارتكب الشر في عيني الرب إلهه، على نقيض داود أبيه،","16:3":"متمثلا بملوك إسرائيل، حتى إنه أجاز ابنه في النار، وفقا لأرجاس الأمم الذين طردهم الرب من أمام بني إسرائيل.","16:4":"وذبح وأوقد للأوثان على المرتفعات وعلى التلال وتحت كل شجرة خضراء.","16:5":"عندئذ تقدم رصين ملك أرام وفقح بن رمليا ملك إسرائيل نحو أورشليم لمهاجمتها، فحاصرا آحاز. غير أنهما أخفقا في الاستيلاء عليها.","16:6":"وتمكن رصين ملك أرام من استرجاع مدينة أيلة، فطرد منها اليهود وأحل مكانهم الأراميين فاستوطنوها إلى هذا اليوم.","16:7":"وبعث آحاز وفدا إلى تغلث فلاسر ملك أشور قائلا: «أنا عبدك وابنك، فتعال وأنقذني من حصار ملك أرام وملك إسرائيل اللذين يهاجمانني».","16:8":"وجمع آحاز الفضة والذهب الموجودة في هيكل الرب وفي خزائن قصر الملك، وأرسلها إلى ملك أشور هدية.","16:9":"فلبى ملك أشور طلبه، وزحف بجيشه إلى دمشق واستولى عليها، وسبى أهلها إلى قير، وقتل رصين.","16:10":"وتوجه الملك آحاز إلى دمشق للقاء تغلث فلاسر ملك أشور، فشاهد هناك المذبح، فنقل رسمه وأرسله إلى أوريا الكاهن بكامل تفاصيل صناعته.","16:11":"فبنى أوريا الكاهن مذبحا بموجب الرسم الذي بعثه الملك آحاز من دمشق، وانتظر رجوع الملك من سفرته.","16:12":"وعندما عاد الملك من دمشق، وشاهد المذبح","16:13":"أوقد عليه محرقته وتقدمته، وسكب عليه سكيبه من الخمر، ثم رش على المذبح دم ذبيحة السلام.","16:14":"أما مذبح النحاس القائم أمام الرب، بين مدخل الهيكل والمذبح الجديد، فقد أزاحه إلى جانب المذبح الشمالي.","16:15":"وأمر الملك آحاز أوريا الكاهن أن يوقد محرقة الصباح وتقدمة المساء ومحرقة الملك وتقدمته مع محرقة الشعب وتقدمتهم وسكائب خمرهم على المذبح العظيم، ويرش عليه كل دم محرقة وذبيحة. أما مذبح النحاس فيكون مخصصا للملك لمعرفة الغيب","16:16":"فنفذ أوريا الكاهن أوامر الملك آحاز.","16:17":"ثم نزع الملك آحاز عوارض القواعد الدائرية ورفع عنها المرحضة وأنزل البركة عن الثيران النحاسية وأقامها على صف من الحجارة.","16:18":"وإرضاء لملك أشور أزال آحاز من الهيكل منبر العرش الملكي، وأغلق المدخل الخاص الذي كان قد بني من الخارج ليصل ما بين القصر والهيكل.","16:19":"أما بقية أخبار آحاز ومنجزاته أليست هي مدونة في كتاب أخبار أيام ملوك يهوذا؟","16:20":"ثم مات آحاز فدفن مع آبائه في مدينة داود وخلفه ابنه حزقيا على الملك.","17:1":"وفي السنة الثانية عشرة من حكم آحاز ملك يهوذا، اعتلى هوشع بن أيلة عرش إسرائيل في السامرة، لمدة تسع سنوات.","17:2":"وارتكب الشر في عيني الرب، إلا أنه كان أفضل قليلا من أسلافه ملوك إسرائيل.","17:3":"وزحف عليه شلمنأسر ملك أشور فصار هوشع له تابعا يدفع له جزية.","17:4":"ومالبث أن اكتشف ملك أشور خيانة هوشع، الذي أرسل وفدا يستغيث بسوا ملك مصر، ولم يؤد جزية لملك أشور كعهده في كل سنة، فقبض عليه ملك أشور وزجه موثقا في السجن.","17:5":"واجتاح ملك أشور أرض إسرائيل، وحاصر السامرة ثلاث سنوات.","17:6":"وفي السنة التاسعة من حكم هوشع سقطت السامرة، فسبى ملك أشور الإسرائيليين إلى أشور وأسكنهم في مدينة حلح، وعلى ضفاف نهر خابور في منطقة جوزان، وفي مدن مادي.","17:7":"وقد حلت هذه النكبة ببني إسرائيل لأنهم أثموا في حق الرب إلههم الذي أخرجهم من ديار مصر، من تحت نير فرعون وعبدوا آلهة أخرى،","17:8":"سالكين حسب فرائض الأمم الذين طردهم الرب من أمامهم، ومن أمام ملوكهم الذين نصبوهم عليهم.","17:9":"وارتكب بنو إسرائيل في الخفاء معاصي في حق الرب إلههم، وشيدوا لأنفسهم مرتفعات في جميع مدنهم من برج النواطير إلى المدينة المحصنة،","17:10":"وأقاموا لأنفسهم أنصابا وتماثيل لعشتاروث على كل تل مرتفع، وتحت كل شجرة خضراء،","17:11":"وقربوا محرقات على جميع المرتفعات كسائر الأمم الذين نفاهم الرب من أمامهم، واقترفوا الموبقات لإغاظة الرب،","17:12":"عابدين الأصنام التي حذرهم ونهاهم الرب عنها.","17:13":"وقد أنذر الرب إسرائيل ويهوذا عن طريق أنبيائه ورائيه قائلا: «ارجعوا عن طرقكم الأثيمة، وأطيعوا وصاياي وفرائضي بمقتضى كل الشريعة التي أوصيت آباءكم بتطبيقها، والتي أعلنتها لكم على لسان عبيدي الأنبياء.","17:14":"لكنهم أصموا أذانهم وأغلظوا قلوبهم كآبائهم الذين لم يثقوا بالرب إلههم،","17:15":"وتنكروا لفرائضه وعهده الذي أبرمه مع آبائهم، وتجاهلوا تحذيراته ونواهيه لهم، وضلوا وراء أصنام باطلة، فأصبحوا هم أنفسهم باطلين، وتمثلوا بالأمم الذين حولهم، مع أن الرب أمرهم ألا يفعلوا مثلهم، وارتكبوا أمورا نهاهم الرب عنها،","17:16":"ونبذوا جميع وصايا الرب إلههم، وصنعوا لأنفسهم عجلين مسبوكين، وأقاموا تماثيل لعشتاروث وسجدوا لجميع كواكب السماء وعبدوا البعل.","17:17":"وأجازوا أبناءهم وبناتهم في النار، وتعاطوا العرافة والفأل وباعوا أنفسهم لارتكاب الشر في عيني الرب لإثارة غيظه.","17:18":"فاحتدم غضب الرب على إسرائيل، وطردهم من حضرته، ولم يبق سوى سبط يهوذا.","17:19":"ولكن حتى سبط يهوذا لم يحفظ وصايا الرب إلهه بل نهج في طرق إسرائيل التي سلكتها.","17:20":"فنبذ الرب كل ذرية إسرائيل وأذلهم وأسلمهم ليد آسريهم، وطردهم من حضرته.","17:21":"لأنه شق إسرائيل عن بيت داود، فتوجوا يربعام بن نباط ملكا عليهم، فأضل يربعام بني إسرائيل عن طريق الرب واستغواهم فأخطأوا بحق الرب خطيئة عظيمة.","17:22":"ولم يعدل الإسرائيليون عن ارتكاب جميع خطايا يربعام بل أمعنوا في اقترافها","17:23":"فنفى الرب إسرائيل من حضرته كما نطق على لسان جميع عبيده الأنبياء، فسبي الإسرائيليون من أرضهم إلى أشور إلى هذا اليوم.","17:24":"ونقل ملك أشور أقواما من بابل وكوث وعوا وحماة وسفروايم، وأسكنهم مدن السامرة محل بني إسرائيل، فاستولوا على السامرة وأقاموا في مدنها.","17:25":"وإذ لم يعبد المستوطنون الجدد الرب في باديء الأمر، فقد أطلق الرب عليهم السباع المتوحشة فافترست بعضهم.","17:26":"فبعثوا إلى ملك أشور رسالة قائلين: «إن الأقوام الذين قمت بسبيهم وإسكانهم في مدن السامرة يجهلون قضاء إله هذه الأرض، فأطلق عليهم السباع فافترستهم، لأنهم يجهلون قضاءه».","17:27":"فأمر ملك أشور قائلا: «ابعثوا إلى هناك أحد الكهنة المسبيين في تلك البلاد، ليقيم بينهم، ويلقنهم قضاء إله الأرض».","17:28":"فجاء واحد من الكهنة المسبيين من السامرة وأقام في بيت إيل، وشرع يلقنهم كيف يتقون الرب.","17:29":"ومع ذلك ظل كل قوم يصنعون آلهتهم وينصبونها في معابد المرتفعات التي شيدها السامريون في المدن التي يقيمون فيها.","17:30":"فعبد القادمون من بابل أصنام إلههم سكوث بنوث؛ وعبد القادمون من كوث أصنام إلههم نرجل، وعبد القادمون من حماة أصنام إلههم أشيما،","17:31":"كما عبد أهل عوا نبحز وترتاق. أما أهل سفروايم فكانوا يحرقون أبناءهم بالنار قرابين لأدرملك وعنملك إلهي سفروايم.","17:32":"فكانوا يعبدون الرب، ولكنهم أيضا أقاموا من بينهم كهنة يخدمون في معابد المرتفعات، ويقربون محرقاتهم فيها.","17:33":"وهكذا كانوا يتقون الرب من ناحية، ويعبدون آلهتهم التي حملوها معهم من بين الأمم التي سبوا منها من ناحية أخرى.","17:34":"فهم إلى هذا اليوم، يمارسون طقوسهم الأولى. فأصبحت عبادتهم خليطا من تقوى الرب ومن الطقوس والفرائض الوثنية، وفقا لتقاليدهم، وليس بمقتضى شريعة الرب والوصية التي أمر بها ذرية يعقوب الذي حول اسمه إلى إسرائيل.","17:35":"فقد قطع الرب مع بني إسرائيل عهدا وأمرهم ألا يعبدوا آلهة أخرى ولا يسجدوا لها ولا يتقوها ولا يقربوا لها الذبائح،","17:36":"بل يتقون الرب الذي أخرجهم من ديار مصر بقوة عظيمة وذراع مقتدرة، وله وحده يسجدون ويقربون المحرقات،","17:37":"ويطيعون الفرائض والأحكام والشريعة والوصية التي كتبها لهم ليمارسوها كل حياتهم ولا يتقون آلهة أخرى.","17:38":"ولا ينقضون العهد الذي أبرمه معهم ولا يتقون آلهة أخرى.","17:39":"إنما يتقون الرب إلههم وهو ينجيهم من جميع أعدائهم.","17:40":"ولكن هؤلاء السكان أصموا آذانهم ومارسوا طقوسهم القديمة،","17:41":"فكانوا يتقون الرب من ناحية، ويعبدون أوثانهم من ناحية أخرى. واقتفى بنوهم خطاهم في ممارساتهم إلى هذا اليوم.","18:1":"وفي السنة الثالثة لحكم هوشع بن أيلة ملك إسرائيل، اعتلى حزقيا بن آحاز عرش يهوذا،","18:2":"وكان له من العمر خمس وعشرون سنة حين ملك، ودام حكمه في أورشليم تسعا وعشرين سنة، واسم أمه أبي ابنة زكريا،","18:3":"وصنع ما هو صالح في عيني الرب على نهج أبيه داود،","18:4":"فأزال معابد المرتفعات، وحطم التماثيل، وقطع أصنام عشتاروث، وسحق حية النحاس التي صنعها موسى لأن بني إسرائيل ظلوا حتى تلك الأيام يوقدون لها، ودعوها نحشتان.","18:5":"واتكل على الرب إله إسرائيل فلم يأت قبله ولا بعده ملك نظيره بين ملوك يهوذا.","18:6":"والتصق بالرب ولم يحد عن طريقه، بل أطاع وصاياه التي أمر بها الرب موسى.","18:7":"لذلك كان الرب معه وكلل أعماله بالنجاح. وثار على ملك أشور وأبى الخضوع له،","18:8":"ودحر الفلسطينيين من برج النواطير إلى المدينة المحصنة حتى بلغ غزة وضواحيها.","18:9":"وفي السنة الرابعة لحكم الملك حزقيا، الموافقة للسنة السابعة لاعتلاء هوشع بن أيلة عرش إسرائيل، زحف شلمنأسر ملك أشور على السامرة وحاصرها،","18:10":"وتمكن من الاستيلاء عليها في نهاية ثلاث سنوات، أي في السنة السادسة لملك حزقيا، الموافقة للسنة التاسعة لحكم هوشع ملك إسرائيل.","18:11":"وسبى ملك أشور سكان إسرائيل إلى أشور، وأسكنهم في مدينة حلح وعلى ضفاف نهر خابور في منطقة جوزان وفي مدن مادي،","18:12":"لأنهم أبوا الاستماع لصوت الرب إلههم، ونكثوا عهده وكل ما أمر به موسى عبد الرب، ولم يعملوا بها.","18:13":"وفي السنة الرابعة عشرة من حكم الملك حزقيا اجتاح سنحاريب ملك أشور جميع مدن يهوذا الحصينة واستولى عليها.","18:14":"وأرسل حزقيا ملك يهوذا يقول لملك أشور في لخيش: «أخطأت، فارتحل عني، وأنا أدفع ما تفرضه علي من جزية». ففرض ملك أشور على حزقيا ملك يهوذا ثلاث مئة وزنة (نحو ألف وثمانين كيلوجراما من الفضة)، وثلاثين وزنة (نحو مائة وثمانية كيلوجرامات من الذهب).","18:15":"فجمع حزقيا كل ما في بيت الرب وخزائن قصر الملك من فضة وذهب ودفعها له.","18:16":"كما قشر الذهب الذي كان قد غشى به أبواب هيكل الرب والدعائم، وبعث به إلى ملك أشور.","18:17":"ورغم ذلك أرسل ملك أشور إلى حزقيا قائد جيشه ووزير خزائنه ورئيس أركان قواته من لخيش، على رأس جيش جرار لمحاصرة أورشليم. فزحفوا عليها، وأحاطوا بها وعسكروا عند قناة البركة العليا في طريق حقل القصار.","18:18":"فاستدعوا الملك. فبعث حزقيا إليهم ألياقيم بن حلقيا مدير شئون القصر. وشبنة الكاتب ويواخ بن آساف مسجل الملك.","18:19":"فقال لهم قائد جيش أشور: «بلغوا حزقيا أن هذا ما يقوله الملك العظيم، ملك أشور: على ماذا تتكل؟","18:20":"أظننت أن مجرد الكلام يشكل خطة وقوة لخوض الحرب؟ على من اعتمدت حتى تمردت علي؟","18:21":"ها أنت تتكل على عكاز هذه القصبة المرضوضة مصر، التي تثقب كف كل من يتوكأ عليها! هكذا يكون فرعون ملك مصر لكل من يتكل عليه!","18:22":"وإذا قلتم لي إنكم توكلتم على الرب إلهكم. أفليس هو الذي أزال حزقيا مرتفعاته ومذابحه، وأمر يهوذا وأهل أورشليم أن يسجدوا فقط أمام هذا المذبح القائم في أورشليم؟","18:23":"والآن ليعقد حزقيا رهانا مع سيدي ملك أشور، فأعطيك ألفي فرس، إن استطعت أن تجد لها فرسانا يمتطونها.","18:24":"فكيف يمكنك أن تصد قائدا واحدا من أقل قادة سيدي شأنا، في حين أنك تعتمد على مصر لإمدادك بالمركبات والفرسان؟","18:25":"ثم هل من غير مشورة الرب زحفت على هذه الديار لأدمرها؟ لقد قال لي الرب هاجم هذه الديار وخربها».","18:26":"فقال ألياقيم بن حلقيا وشبنة ويواخ لقائد الجيش: «خاطب عبيدك بالأرامية لأننا نفهمها، ولا تخاطبنا باللغة اليهودية لئلا يسمع الشعب المتجمع على السور».","18:27":"فأجابهم قائد الجيش: «أتظن أن سيدي قد أرسلنا لنتحدث إليكم وإلى ملككم فقط بهذا الكلام؟ أليس هذا الكلام موجها إلى الرجال المتجمعين على السور الذين سيأكلون مثلكم برازهم ويشربون بولهم؟»","18:28":"ثم وقف قائد الجيش ونادى بأعلى صوته قائلا باليهودية: «اسمعوا كلام الملك العظيم ملك أشور.","18:29":"لا يخدعكم حزقيا لأنه عاجز عن إنقاذكم","18:30":"ولا يقنعكم حزقيا بالاتكال على الرب قائلا: إنه حتما ينقذنا ولن يستولي ملك أشور على هذه المدينة.","18:31":"لا تصغوا إليه لأنه هكذا يقول ملك أشور: اعقدوا معي صلحا، واستسلموا إلي، فيأكل عندئذ كل واحد من كرمه ومن تينته ويشرب من بئره.","18:32":"إلى أن آتي وأنقلكم إلى أرض كأرضكم، أرض حنطة وخمر وخبز وكروم وزيتون وعسل. فاحيوا ولا تموتوا. لا تصغوا إلى حزقيا لأنه يغريكم بقوله إن الرب لابد أن ينقذنا.","18:33":"فهل أنقذت آلهة الأمم أراضيها من ملك أشور؟","18:34":"أين آلهة حماة وأرفاد؟ أين آلهة سفروايم وهينع وعوا؟ هل أنقذت السامرة من يدي؟","18:35":"من من كل آلهة البلاد التي استوليت عليها أنقذ أرضه من يدي، حتى ينقذ الرب أورشليم مني؟»","18:36":"فصمت الشعب ولم يجبه أحد بكلمة، لأن الملك أمرهم بعدم الرد عليه.","18:37":"ثم رجع ألياقيم بن حلقيا مدير شؤون القصر، وشبنة الكاتب ويواخ بن آساف المسجل إلى حزقيا بثياب ممزقة، وأبلغوه كلام القائد الأشوري.","19:1":"وعندما سمع الملك حزقيا ذلك مزق ثيابه وارتدى مسوحا ولجأ إلى بيت الرب.","19:2":"ثم أرسل ألياقيم مدير شؤون القصر وشبنة الكاتب ورؤساء الكهنة وهم مرتدون المسوح إلى النبي إشعياء بن آموص،","19:3":"فقالوا له: «هذا ما يقوله حزقيا: هذا اليوم هو يوم ضيق وإهانة وكرب، فإننا كالأجنة المشرفة على الولادة من غير أن تتوافر لها القوة على ذلك.","19:4":"فلعل الرب إلهك يسمع وعيد القائد الأشوري الذي أوفده سيده ملك أشور، ليهين الإله الحي فيعاقبه الرب إلهك على ما صدر منه من تعيير، فصل من أجل البقية الناجية منا».","19:5":"فجاء رجال الملك حزقيا لإشعياء،","19:6":"فقال لهم إشعياء: «بلغوا سيدكم: هذا ما يقوله الرب: لا تجزع مما سمعته من تجديف رجال ملك أشور علي.","19:7":"فها خبر سييء يرد إليه من بلاده يحمله على العودة إليها حيث أقضي عليه بحد السيف في عقر داره».","19:8":"وعندما علم قائد الجيش الأشوري بأن ملك أشور قد ارتحل عن لخيش وشرع في محاربة لبنة، انسحب هو أيضا وانضم إليه هناك.","19:9":"وبلغ ملك أشور أن ترهاقة ملك كوش قد خرج لمحاربته، فبعث مرة أخرى رسلا إلى حزقيا قائلا:","19:10":"«هذا ما تبلغونه إلى حزقيا ملك يهوذا: لا يخدعك إلهك الذي تتكل عليه عندما يقول لن تسقط أورشليم في قبضة ملك أشور،","19:11":"فها أنت قد علمت بما ألحقه ملوك أشور بكل البلدان من تدمير كامل فهل يمكن أن تنجو أنت؟","19:12":"هل أنقذت آلهة الأمم الأخرى أهل جوزان وحاران ورصف وبني عدن الذين في تلاسار الذين أفناهم آبائي؟","19:13":"أين ملك حماة وملك أرفاد وملك مدينة سفروايم وهينع وعوا؟»","19:14":"فتناول حزقيا الكتاب من أيدي الرسل وقرأه، ثم توجه إلى هيكل الرب وبسطه أمامه.","19:15":"وصلى قائلا: «أيها الرب إله إسرائيل، المتربع فوق الكروبيم، أنت وحدك إله كل ممالك الأرض. أنت وحدك خلقت السماوات والأرض.","19:16":"أرهف يارب أذنيك واستمع. افتح يارب عينيك وانظر، واسمع كل تهديدات سنحاريب التي أرسلها ليعير الله الحي.","19:17":"حقا يارب إن ملوك أشور قد أهلكوا الأمم ودمروا ديارهم،","19:18":"وطرحوا آلهتهم إلى النار وأبادوها لأنها ليست فعلا آلهة بل خشبا وحجارة من صنعة أيدي الناس،","19:19":"فخلصنا الآن أيها الرب إلهنا من يده، فتدرك ممالك الأرض بأسرها أنك أنت وحدك الرب الإله».","19:20":"فبعث إشعيا بن آموص إلى حزقيا قائلا: «هذا ما يقوله الرب إله إسرائيل الذي تضرعت إليه لينقذك من سنحاريب ملك أشور: قد سمعت».","19:21":"وهذا هو رد الرب عليه: «ها العذراء ابنة صهيون قد احتقرتك واستهزأت بك، وهزت ابنة أورشليم رأسها سخرية منك.","19:22":"من عيرت وجدفت عليه؟ وعلى من رفعت صوتا وشمخت بعينيك زهوا؟ أعلى قدوس إسرائيل؟","19:23":"لقد عيرت السيد على لسان رسلك، وقلت: بكثرة مركباتي قد صعدت إلى أعالي الجبال، وبلغت أقاصي لبنان قاطعا أطول أرزه وخيار سروه واخترقت أبعد ربوعه وأفضل غاباته.","19:24":"قد حفرت آبارا في أرض غريبة وشربت مياها، وبباطن قدمي جففت جميع خلجان مصر.","19:25":"ألم تسمع؟ منذ زمن طويل قدرت ذلك. منذ الأيام القديمة قررته وها أنا الآن أحققه، إذ أقمتك لتدمير مدن محصنة فتحولها إلى روابي خربة.","19:26":"وقد خارت قوى أهلها فأصبحوا مرتاعين خجلين، صاروا كعشب الحقل، كالنبات اللين وكحشيش السطوح الذاوي قبل نموه.","19:27":"ولكني مطلع على حركاتك وسكناتك وهيجانك علي.","19:28":"ولأن ثورتك علي وعجرفتك قد بلغتا مسامعي، فإني سأشكمك بخزامتي في أنفك، وأضع لجامي في فمك، وأعيدك في نفس الطريق الذي أقبلت منه.","19:29":"وهذه علامة لك ياحزقيا: في هذه السنة تأكلون مما نبت من نفسه، وفي السنة الثانية تأكلون مما ينبت عنه، وأما في السنة الثالثة فتزرعون فيها وتحصدون وتغرسون كروما وتجنون أثمارها.","19:30":"ويعود الناجون الباقون من بيت يهوذا، فتتأصل جذورهم في الأرض، ويحملون أثمارا على أغصانهم،","19:31":"لأن من أورشليم تخرج البقية، ومن جبل صهيون يأتي الناجون، فغيرة الرب القدير تصنع هذا.","19:32":"لذلك فهذا ما يقوله الرب عن ملك أشور: لن يدخل هذه المدينة ولن يطلق عليها سهما أو يتقدم نحوها بترس ولن يقيم عليها مقلاعا.","19:33":"بل يرجع في الطريق الذي جاء منه، ولن يدخل هذه المدينة، يقول الرب.","19:34":"لأنني أدافع عنها، وأنقذها من أجل نفسي، وإكراما لداود عبدي».","19:35":"وحدث في تلك الليلة أن ملاك الرب قتل مئة وخمسة وثمانين ألفا من جيش الأشوريين، فما إن طلع الصباح حتى كانت الجثث الميتة تملأ المكان.","19:36":"فانسحب سنحاريب ملك أشور وارتد إلى بلاده ومكث في نينوى.","19:37":"وفيما هو يتعبد في هيكل إلهه نسروخ، اغتاله ابناه، أدرملك وشرآصر، وفرا إلى أرض أراراط، فخلفه ابنه آسرحدون على العرش.","20:1":"ومرض حزقيا في تلك الأيام حتى أشرف على الموت، فجاء إليه إشعياء بن آموص قائلا: «هذا ما يقوله الرب: «نظم شؤون بيتك لأنك لن تبرأ بل حتما تموت».","20:2":"فأشاح بوجهه نحو الحائط وصلى قائلا:","20:3":"«آه يارب، اذكر كيف سلكت أمامك بأمانة وإخلاص قلب، وصنعت ما يرضيك». وبكى حزقيا بكاء مرا.","20:4":"وقبل أن يبلغ إشعياء فناء القصر الأوسط خاطبه الرب قائلا:","20:5":"«ارجع وقل لحزقيا رئيس شعبي: هذا ما يقوله الرب إله داود أبيك: قد سمعت صلاتك، ورأيت دموعك، وها أنا أبرئك، فتذهب في اليوم الثالث للصلاة في هيكل الرب.","20:6":"وأضيف على سني حياتك خمسة عشر عاما وأنقذك أنت وهذه المدينة من ملك أشور، وأدافع عنها من أجل نفسي وإكراما لعبدي داود».","20:7":"ثم قال إشعياء: «خذوا قرص تين». فأخذوا قرص تين وضعوه على القرح فبرىء.","20:8":"وسأل حزقيا إشعياء: «ما العلامة أن الرب يشفيني، فأتمكن من الذهاب إلى هيكل الرب في اليوم الثالث؟»","20:9":"فأجابه إشعيا: «إليك العلامة من الرب بأنه مزمع أن يتمم ما وعد به. أجبني هل يتقدم الظل عشر درجات أم يرتد عشر درجات؟»","20:10":"فأجاب حزقيا: «من شأن الظل أن يتقدم عشر درجات، لذلك ليرتد الظل إلى الوراء عشر درجات، فتكون هذه هي العلامة».","20:11":"فابتهل إشعياء إلى الرب، فتراجع الظل إلى الوراء عشر درجات فوق سلم آحاز، بعد أن كان الظل قد امتد عليها إلى الأمام عشر درجات.","20:12":"وعندما علم برودخ بلادان ابن الملك البابلي بلادان بمرض حزقيا، بعث إليه (وفدا) ورسائل وهدايا.","20:13":"فاحتفى بهم حزقيا، وأطلعهم على كل ما في خزائن نفائسه من فضة وذهب وأطياب وعطور، وعلى كل مخازن أسلحته، وعلى كل ما يحتفظ به في خزائنه. لم يترك شيئا في قصره وفي كل مملكته لم يطلعهم عليه.","20:14":"فوفد إشعياء النبي على الملك حزقيا وسأله: «ماذا قال هؤلاء الرجال، ومن أين جاءوا؟» فأجابه: «جاءوا من أرض بعيدة، من بابل».","20:15":"فعاد يسأله: «ماذا شاهدوا في قصرك؟» فأجاب حزقيا: «شاهدوا كل ما في قصري. لم أترك شيئا في مخازني لم أطلعهم عليه».","20:16":"فقال إشعياء لحزقيا: «اسمع كلام الرب.","20:17":"ها أيام تأتي ينقل فيها إلى بابل كل ما في قصرك، وما ادخره أسلافك إلى هذا اليوم، ولا يبقى منها شيء، يقول الرب.","20:18":"ويسبى بعض أبنائك الخارجين من صلبك ليكونوا خصيانا في قصر ملك بابل».","20:19":"فقال حزقيا لإشعياء: «صالح قول الرب الذي أعلنته». ثم حدث نفسه: «لم لا؟ إن كان السلام والأمان يسودان في أيامي».","20:20":"أما بقية أخبار حزقيا وكل أعماله ومنجزاته، وكيف صنع البركة والقناة، وأدخل الماء إلى المدينة، أليست مدونة في كتاب أخبار أيام ملوك يهوذا؟","20:21":"ثم مات حزقيا، ودفن مع آبائه، وخلفه ابنه منسى على الملك.","21:1":"كان منسى في الثانية عشرة من عمره عندما تولى مقاليد الحكم، وظل ملكا في أورشليم مدة خمس وخمسين سنة، واسم أمه حفصيبة.","21:2":"وارتكب الشر في عيني الرب، مقترفا رجاسات الأمم الذين طردهم الرب من أمام بني إسرائيل،","21:3":"فعاد وشيد معابد المرتفعات التي هدمها أبوه حزقيا، وأقام مذابح البعل، ونصب تماثيل عشتاروث على غرار ما صنع أخآب، وسجد لكواكب السماء وعبدها.","21:4":"وبنى مذابح في هيكل الرب في أورشليم الذي قال عنه الرب: «في أورشليم أجعل اسمي».","21:5":"وبنى في داري هيكل الرب مذابح لكل كواكب السماء.","21:6":"وأجاز ابنه في النار، ورصد الأوقات ولجأ إلى أصحاب الجان والعرافين وأوغل في ارتكاب الشر مما أثار عليه غضب الله الرهيب.","21:7":"ونصب تمثال عشتاروث الذي صنعه، في الهيكل الذي قال الرب عنه لداود وسليمان: «في هذا الهيكل، وفي أورشليم التي اخترتها من الأرض، التي وهبتها لآبائهم، أجعل اسمي إلى الأبد.","21:8":"فإذا أطاع بنو إسرائيل وعملوا كل ما أمرتهم به، وطبقوا الشريعة التي أوصاهم بها عبدي موسى، فإنني لن أزعزع أقدامهم من الأرض التي وهبتها لآبائهم».","21:9":"لكنهم عصوا، بل أضلهم منسى فارتكبوا ما هو أقبح مما ترتكبه الأمم التي طردها الرب من أمام بني إسرائيل.","21:10":"ثم قال الرب على لسان عبيده الأنبياء:","21:11":"«لأن منسى ملك يهوذا اقترف جميع هذه الموبقات، وارتكب شرورا أشد فظاعة من شرور الأموريين الذين كانوا قبله، وأضل يهوذا فجعله يأثم بعبادة أصنامه،","21:12":"لذلك يقول الرب إله إسرائيل: ها أنا أجلب شرا على أورشليم ويهوذا، فتطن أذنا كل من يسمع به.","21:13":"وسأوقع على أورشليم العقاب الذي أوقعته بالسامرة، وبأخآب ونسله. وأمسح أورشليم من الوجود كما يمسح الطبق من بقايا الطعام، ثم يقلب على وجهه ليجف.","21:14":"وأنبذ بقية شعبي وأسلمهم إلى أيدي أعدائهم، فيصبحون غنيمة وأسرى لهم،","21:15":"لأنهم ارتكبوا الشر في عيني، وأثاروا سخطي منذ خروج آبائهم من مصر إلى هذا اليوم.","21:16":"وزاد منسى فسفك دم أبرياء كثيرين، حتى ملأ أورشليم من أقصاها إلى أقصاها، فضلا عن خطيئته التي استغوى بها يهوذا، وجعله يرتكب الشر في عيني».","21:17":"أما بقية أخبار منسى ومنجزاته وما ارتكب من خطيئة، أليست هي مدونة في كتاب أخبار أيام ملوك يهوذا؟","21:18":"ثم مات منسى ودفن في حديقة قصره، في حديقة عزا. وخلفه ابنه آمون.","21:19":"وكان آمون في الثانية والعشرين من عمره حين ملك، ودام حكمه سنتين في أورشليم، واسم أمه مشلمة بنت حاروص من يطبة،","21:20":"وارتكب الشر في عيني الرب مثل أبيه.","21:21":"لم يحد عن طريق أبيه، وعبد الأصنام التي عبدها أبوه وسجد لها.","21:22":"وتخلى عن الرب إله آبائه، ولم يتبع طريقه.","21:23":"وتآمر عليه رجاله واغتالوه في قصره،","21:24":"غير أن الشعب هاجم قتلة الملك آمون وقضى عليهم، ونصب يوشيا ابنه خلفا له.","21:25":"أما بقية أخبار آمون ومنجزاته أليست هي مدونة في كتاب أخبار أيام ملوك يهوذا.","21:26":"ودفن في قبره في حديقة عزا وخلفه ابنه يوشيا على الملك.","22:1":"كان يوشيا بن آمون في الثامنة من عمره حين ملك. ودام حكمه إحدى وثلاثين سنة في أورشليم، واسم أمه يديدة بنت عداية من بصقة.","22:2":"وعمل ما هو صالح في عيني الرب، وسار في نهج جده داود ولم يحد عن طريقه يمينا أو شمالا.","22:3":"وفي السنة الثامنة عشرة لحكم الملك يوشيا، بعث الملك الكاتب شافان بن أصليا بن مشلام إلى هيكل الرب قائلا:","22:4":"«اذهب إلى حلقيا رئيس الكهنة، واطلب إليه أن يحسب قيمة الفضة التي تبرع بها أبناء الشعب وجمعها منهم حراس الباب،","22:5":"فيعطيها للموكلين على الإشراف على العمل في هيكل الرب، فيدفعها هؤلاء إلى القائمين بالعمل في بيت الرب لترميم ثغرات الهيكل،","22:6":"من بنائين ونجارين، ولشراء الأخشاب والحجارة المنحوتة لترميم الهيكل».","22:7":"ولم يطلب من هؤلاء الموكلين على العمل تقديم أي حساب عن الفضة المدفوعة لهم لنزاهتهم.","22:8":"ثم قال حلقيا رئيس الكهنة لشافان الكاتب: «لقد عثرت على سفر الشريعة في الهيكل». وسلم حلقيا السفر لشافان فقرأه.","22:9":"وحمله إلى الملك، بعد أن قدم له تقريرا قائلا: «قد حسب عبيدك الفضة الموجودة في الهيكل وأودعوها لدى الموكلين على الإشراف على العمل في الهيكل».","22:10":"ثم أطلع شافان الكاتب الملك على السفر قائلا: «قد أعطاني حلقيا سفرا». وقرأه شافان أمام الملك","22:11":"فلما سمع الملك ما ورد في سفر الشريعة مزق ثيابه،","22:12":"وأمر حلقيا الكاهن، وأخيقام بن شافان، وعكبور بن ميخا، وشافان الكاتب، وعسايا خادم الملك قائلا:","22:13":"«اذهبوا واسألوا الرب عن مصيري ومصير شعب يهوذا بناء على ما ورد في هذا السفر الذي تم العثور عليه، إذ إن غضب الرب المحتدم علينا عظيم جدا، لأن آباءنا لم يطيعوا كلام هذا السفر، ولم يمارسوا كل ما ورد فيه».","22:14":"فانطلق حلقيا الكاهن، وأخيقام، وعكبور، وشافان، وعسايا، واستشاروا النبية خلدة زوجة شلوم بن تقوة بن حرحس حارس الثياب الملكية، المقيمة في المنطقة الثانية من أورشليم.","22:15":"فقالت لهم: «هذا ما يقوله الرب إله إسرائيل: قولوا للرجل الذي أرسلكم إلي:","22:16":"هكذا يقول الرب: ها أنا أجلب على هذا الموضع وعلى أهله كل الوعيد الوارد في السفر الذي قرأه ملك يهوذا،","22:17":"لأنهم نبذوني وأوقدوا لآلهة أخرى، ليثيروا سخطي بما تجنيه أيديهم من آثام، فاحتدم غضبي الذي لا ينطفيء على هذا الموضع.","22:18":"أما ملك يهوذا الذي أرسلكم لتستشيروا الرب، فهذا ما تقولون له: إليك ما يقول الرب إله إسرائيل بشأن ما سمعت من كلام:","22:19":"من حيث أن قلبك قد رق، وتواضعت أمام الرب لدى سماعك ما قضيت به على هذا الموضع وعلى أهله، بأن يصيروا مثار دهشة ولعنة، ومزقت ثيابك وبكيت أمامي، فإنني قد استجبت أنا أيضا رجاءك.","22:20":"لذلك ها أنا أتوفاك فتدفن في قبرك بسلام، ولا تشهد عيناك ما سأنزله بهذا الموضع من شر». فحمل الرجال ردها إلى الملك يوشيا.","23:1":"عندئذ أرسل الملك فاستدعى إليه كل شيوخ يهوذا وأورشليم،","23:2":"وتوجه معهم إلى هيكل الرب، يرافقه جميع شيوخ يهوذا وكل سكان أورشليم والكهنة والأنبياء وجميع أبناء الشعب من صغار وكبار، فقرأ في مسامعهم كل كلام سفر الشريعة الذي تم العثور عليه في بيت الرب.","23:3":"ووقف الملك على المنبر وقطع عهدا أمام الرب أن يتبع الرب، حافظا وصاياه وشهاداته وفرائضه من كل القلب والنفس، لتطبيق كلام هذا العهد المدون في هذا السفر. فوعد الشعب بالوفاء بهذا العهد.","23:4":"وأمر الملك حلقيا رئيس الكهنة، وكهنة الفرقة الثانية، وحراس الباب، أن يطرحوا من هيكل الرب جميع الآنية المصنوعة للبعل ولعشتاروث ولكل كواكب السماء. وأحرقها خارج أورشليم في حقول وادي قدرون، وحمل رمادها إلى بيت إيل.","23:5":"وأباد كهنة الأصنام الذين أقامهم ملوك يهوذا ليوقدوا على مذابح المرتفعات في مدن يهوذا وضواحي أورشليم، وكذلك قضى على الكهنة الذين يحرقون للبعل وللشمس والقمر وللأبراج الفلكية ولسائر الكواكب.","23:6":"وأخرج تمثال عشتاروث من هيكل الرب إلى خارج أورشليم إلى وادي قدرون، وأحرقه وسحقه إلى أن أصبح غبارا، وذرى الغبار على قبور عامة الشعب.","23:7":"وهدم بيوت ذوي الشذوذ الجنسي القائمة حوالي هيكل الرب، حيث كانت النساء ينسجن ثيابا لتمثال عشتاروث.","23:8":"واستدعى يوشيا جميع الكهنة من مدن يهوذا، ودنس كل أماكن العبادة الوثنية في التلال، حيث كان الكهنة يوقدون من جبع إلى بئر سبع، وهدم المرتفعات التي كانت قائمة عند مدخل قصر يشوع محافظ المدينة، إلى الجانب الأيسر من باب المدينة.","23:9":"ولم يدع كهنة المرتفعات يستخدمون مذبح الرب في أورشليم وإن شاركوا بقية إخوتهم الكهنة في أكل خبز الفطير،","23:10":"ودنس الملك أيضا مذبح توفة في وادي بني هنوم، لكي لا يجيز أحد ابنه أو ابنته في النار للصنم مولك.","23:11":"وأباد الخيل التي كرسها ملوك يهوذا لإله الشمس عند مدخل بيت الرب بجوار حجرة نثنملك مدير شؤون القصر، وأحرق المركبات المكرسة لعبادة الشمس.","23:12":"وهدم الملك المذابح التي على سطح علية آحاز التي أقامها ملوك يهوذا، وأيضا المذابح التي بناها منسى في ساحتي الهيكل، وسحق حجارتها هناك ثم ذراها في وادي قدرون","23:13":"ونجس الملك جميع المرتفعات المواجهة لأورشليم، القائمة عن يمين جبل الهلاك، التي بناها سليمان ملك إسرائيل لعشتاروث إلهة صيدون الرجسة، ولكموش إله موآب النجس، ولملكوم إله بني عمون المقيت.","23:14":"وحطم التماثيل، وقطع أعمدة الأصنام، وملأ مكانها من عظام الناس.","23:15":"وكذلك هدم المذبح الذي شيده يربعام بن نباط في مرتفعة بيت إيل، واستغوى بذلك الإسرائيليين فأخطأوا. ثم أحرق المذبح وسحق المرتفعة، حتى تحولت إلى غبار، وأحرق عمود الصنم.","23:16":"وتلفت الملك يوشيا حوله فشاهد مقابر منتشرة على الجبل، فأرسل وجمع عظامها وأحرقها على المذبح، ونجسه تتميما لقضاء الرب الذي نطق به رجل الله بشأن مذبح يربعام.","23:17":"وسأل الملك: «ما هذا النصب الذي أراه؟» فأجابه رجال المدينة: «هو قبر رجل الله الذي جاء من يهوذا وأنبأ بكل ما أجريته على بيت إيل».","23:18":"فقال: «دعوه. لا يحرك أحد عظامه». فتركوا عظامه وعظام نبي السامرة.","23:19":"وأزال يوشيا جميع معابد المرتفعات المنتشرة في مدن السامرة، التي بناها ملوك إسرائيل لإثارة سخط الرب، وأجرى عليها ما أجراه على بيت إيل.","23:20":"وقتل جميع كهنة المرتفعات التي هناك على المذابح، وأحرق عظام الناس عليها. ثم عاد إلى أورشليم.","23:21":"وأمر الملك جميع الشعب قائلا: «احتفلوا بفصح الرب إلهكم كما هو مدون في سفر العهد هذا».","23:22":"إذ لم يكن قد احتفل بعيد الفصح هذا منذ أيام القضاة الذين حكموا على إسرائيل، ولا في كل حقبة ملوك إسرائيل وملوك يهوذا.","23:23":"ولكن في السنة الثامنة عشرة لحكم الملك يوشيا احتفل بهذا الفصح للرب في أورشليم","23:24":"وأباد يوشيا أيضا السحرة والعرافين وأصنام الآلهة التي يتعبد لها الناس في منازلهم، والأوثان وجميع الرجاسات التي استشرت في أرض يهوذا وفي أورشليم، وذلك ليطبق ما ورد في الشريعة المدونة في السفر الذي عثر عليه حلقيا رئيس الكهنة في الهيكل.","23:25":"ولم يقم ملك مثله من قبل ولا من بعد، رجع إلى الرب بكل قلبه ونفسه وقوته بمقتضى شريعة موسى.","23:26":"غير أن الرب لم يرجع عن شدة غضبه، لأن غضبه احتدم على يهوذا لفرط ما أثار منسى من سخطه.","23:27":"فقال الرب: «سأستأصل يهوذا من أمامي كما استأصلت إسرائيل، وأتنكر لأورشليم، المدينة التي اخترتها، وللهيكل الذي قلت يكون اسمي فيه».","23:28":"أما بقية أخبار يوشيا وكل منجزاته أليست هي مدونه في كتاب أخبار أيام ملوك يهوذا؟","23:29":"وفي أيام حكم يوشيا زحف فرعون نخو ملك مصر نحو نهر الفرات لمحاربة ملك أشور، فهب يوشيا لمساعدة ملك أشور عند مجدو، فقتله ملك مصر، في أثناء المعركة.","23:30":"فحمله رجاله في مركبة وعادوا به من مجدو لأورشليم، حيث دفنوه في قبره. فولى الشعب يهوآحاز بن يوشيا ملكا عليهم خلفا لأبيه.","23:31":"وكان يهوآحاز في الثالثة والعشرين من عمره حين ملك، ودام حكمه ثلاثة أشهر في أورشليم، واسم أمه حموطل بنت إرميا من لبنة.","23:32":"وارتكب الشر في عيني الرب على غرار ما فعل آباؤه.","23:33":"واعتقل فرعون نخو يهوآحاز وقيده في ربلة في أرض حماة لئلا يملك في أورشليم، وفرض جزية على البلاد: مئة وزنة من الفضة (نحو ثلاث مئة وستين كيلو جراما)، ووزنة من الذهب (نحو ثلاثة كيلوجرامات).","23:34":"ونصب فرعون نخو ألياقيم بن يوشيا خلفا ليوشيا أبيه، وغير اسمه إلى يهوياقيم. ثم ساق يهوآحاز أسيرا إلى مصر حيث مات.","23:35":"وأدى يهوياقيم جزية الفضة والذهب لفرعون، إلا أنه فرض ضرائب على أهل البلاد ليتمكن من دفعها، بحسب ما يمتلكون.","23:36":"وكان يهوياقيم في الخامسة والعشرين من عمره حين ملك، ودام حكمه إحدى عشرة سنة في أورشليم، واسم أمه زبيدة بنت فداية من رومة.","23:37":"وارتكب الشر في عيني الرب على غرار ما فعل آباؤه.","24:1":"وفي غضون حكمه هاجم نبوخذناصر ملك بابل مملكة يهوذا، فخضع له يهوياقيم طوال ثلاث سنوات، ثم تمرد عليه.","24:2":"فأرسل الرب غزاة من كلدانيين وأراميين وموآبيين وعمونيين للإغارة على مملكة يهوذا وإبادتها، بموجب ما قضى به الرب على لسان عبيده الأنبياء.","24:3":"وقد قضى الرب بذلك ليستأصل إسرائيل من أمامه بسبب ما ارتكبه منسى من آثام،","24:4":"وانتقاما للدم البريء الذي سفكه، إذ إنه ملأ أورشليم بدماء الأبرياء، فلم يشإ الرب أن يصفح عنه.","24:5":"أما بقية أخبار يهوياقيم وأعماله أليست هي مدونة في كتاب أخبار أيام ملوك يهوذا؟","24:6":"ثم مات يهوياقيم، وخلفه ابنه يهوياكين.","24:7":"ولم يعد ملك مصر يخرج من دياره، لأن ملك بابل استولى على كل الأراضي الواقعة من حدود مصر الشمالية إلى نهر الفرات، والتي كانت مصر تحتلها.","24:8":"وكان يهوياكين في الثامنة عشرة من عمره حين ملك، ودام حكمه ثلاثة أشهر في أورشليم، واسم أمه نحوشتا بنت ألناثان من أورشليم.","24:9":"وا رتكب الشر في عيني الرب على غرار ما فعل أبوه.","24:10":"وفي أيامه زحف قادة نبوخذناصر ملك بابل على أورشليم وحاصروا المدينة.","24:11":"ثم جاء نبوخذناصر ملك بابل بنفسه في أثناء حصار المدينة وتسلم زمام القيادة،","24:12":"فاستسلم يهوياكين ملك يهوذا وأمه ورجاله وقادته وخصيانه إلى ملك بابل، فقبض عليه نبوخذناصر. وكان ذلك في السنة الثامنة لملكه.","24:13":"واستولى على جميع ما في خزائن الهيكل وخزائن القصر، وحطم كل آنية الذهب التي صنعها سليمان ملك إسرائيل لهيكل الرب، تماما كما قضى الرب.","24:14":"وسبى نبوخذناصر أهل أورشليم، وكل الرؤساء، وجميع رجال الحرب الأشداء، والخصيان. فكانت جملة المسبيين عشرة آلاف مسبي، كما أخذ الصناع والحدادين، ولم يترك في يهوذا سوى فقراء الشعب المساكين.","24:15":"وسبى يهوياكين وأم الملك ونساءه وخصيانه وعظماء البلاد من أورشليم إلى بابل.","24:16":"كما ساق سبعة آلاف من المحاربين الأشداء وألفا من الصناع والحدادين إلى بابل،","24:17":"وولى ملك بابل متنيا عم يهوياكين خلفا له، بعد أن غير اسمه إلى صدقيا.","24:18":"وكان صدقيا في الحادية والعشرين من عمره حين ملك، ودام حكمه إحدى عشرة سنة في أورشليم، واسم أمه حميطل بنت إرميا من لبنة.","24:19":"وارتكب الشر في عيني الرب، على غرار ما فعل يهوياقيم.","24:20":"ولم يكن ما أصاب أورشليم ويهوذا إلا نتيجة لغضب الرب، الذي نبذهم أخيرا من حضرته. وما لبث صدقيا أن تمرد على ملك بابل.","25:1":"وفي السنة التاسعة لملك صدقيا، في اليوم العاشر من الشهر العاشر، زحف نبوخذناصر ملك بابل بكامل جيشه على أورشليم وحاصرها، وأقام حولها أبراجا.","25:2":"واستمر حصار أورشليم حتى العام الحادي عشر من ملك صدقيا","25:3":"وفي اليوم التاسع من الشهر الرابع من تلك السنة، تفاقمت المجاعة في المدينة، حتى لم يجد أهلها خبزا يأكلونه.","25:4":"وفي تلك الليلة فتح صدقيا ورجاله ثغرة في سور المدينة، وتسلل مع رجاله المحاربين من خلال البوابة القائمة بين السورين نحو حديقة الملك. وكان الكلدانيون محيطين بالمدينة. فتوجه صدقيا ومقاتلوه إلى طريق الصحراء.","25:5":"فتعقبت جيوش الكلدانيين الملك، وأدركته في صحراء أريحا، بعد أن تفرقت قواته عنه.","25:6":"فأسروا الملك واقتادوه إلى ملك بابل المقيم في ربلة، وحرضوه على القضاء عليه.","25:7":"ثم قتلوا أبناء صدقيا على مرأى منه، وقلعوا عينيه، وقيدوه بسلسلتين من نحاس، وساقوه إلى بابل.","25:8":"وفي اليوم السابع من الشهر الخامس من السنة التاسعة عشرة من حكم الملك نبوخذناصر ملك بابل، قدم نبوزرادان قائد الحرس الملكي من بابل إلى أورشليم،","25:9":"وأحرق الهيكل وقصر الملك وسائر بيوت أورشليم، وكل منازل العظماء.","25:10":"وهدمت جيوش الكلدانيين التي تحت إمرة رئيس الحرس الملكي جميع أسوار أورشليم،","25:11":"وسبى نبوزرادان بقية الشعب الذي بقي في المدينة، والهاربين الذين لجأوا إلى ملك بابل وسواهم من السكان.","25:12":"ولكنه ترك فيها فقراء الأرض المساكين ليزرعوها ويفلحوها.","25:13":"وحطم الكلدانيون أعمدة النحاس وبركة النحاس التي في بيت الرب، ونقلوا نحاسها إلى بابل.","25:14":"واستولوا أيضا على القدور والرفوش والمقاص والصحون وجميع آنية النحاس التي كانت تستخدم في الهيكل.","25:15":"وكذلك المجامر والمناضح. كل ما كان مصنوعا من ذهب أخذه قائد الحرس الملكي كذهب، وما كان مصنوعا من فضة كفضة.","25:16":"وكان من العسير وزن النحاس الذي صنع منه سليمان العمودين والبركة الواحدة، والقواعد لهيكل الرب","25:17":"إذ كان ارتفاع العمود يزيد على ثماني عشرة ذراعا (نحو تسعة أمتار)، وقد وضع عليه تاج ارتفاعه ثلاث أذرع (نحو متر ونصف المتر)، تحيط به الشبكة والرمانات النحاسية. وكان العمود الثاني مصنوعا على غرار العمود الأول.","25:18":"وسبى رئيس الحرس الملكي سرايا رئيس الكهنة، وصفنيا مساعده، وحراس الباب الثلاثة.","25:19":"وقبض على خصي واحد من أهل المدينة، كان قائدا للجيش، وعلى خمسة رجال من ندماء الملك الذين تم العثور عليهم في المدينة، وكاتب قائد الجيش المسئول عن التجنيد، وستين رجلا من الفلاحين أهل المدينة.","25:20":"واقتادهم نبوزرادان رئيس الحرس إلى ملك بابل المعسكر في ربلة،","25:21":"فقتلهم ملك بابل في ربلة في أرض حماة. وهكذا سبي شعب يهوذا من أرضه.","25:22":"أما بقية الشعب الذين تركهم نبوخذناصر ملك بابل في أرض يهوذا، فقد وكل عليهم جدليا بن أخيقام بن شافان.","25:23":"ولما علم رؤساء الجيوش ورجالهم أن ملك بابل قد وكل جدليا على الأرض قدموا إليه في المصفاة وهم إسمعيل بن نثنيا، ويوحنان بن قاريح، وسرايا بن تنحومث النطوفاتي، ويازنيا بن المعكي، يرافقهم رجالهم.","25:24":"فحلف جدليا لهم ولرجالهم قائلا: «لا تخافوا من موظفي الكلدانيين. أقيموا في الأرض واخدموا ملك بابل فتنالوا خيرا».","25:25":"ولكن في الشهر السابع جاء إسمعيل بن نثنيا بن أليشمع من النسل الملكي، وعشرة رجال معه واغتالوا جدليا، وقتلوا أيضا اليهود والكلدانيين المقيمين معه في المصفاة.","25:26":"فهب جميع الشعب، صغيرهم وكبيرهم، ورؤساء الجيوش، وهربوا إلى مصر خوفا من انتقام الكلدانيين.","25:27":"وفي السنة السابعة والثلاثين لسبي يهوياكين ملك يهوذا، في اليوم السابع والعشرين من الشهر الثاني عشر، أطلق أويل مرودخ ملك بابل، بمناسبة توليه العرش، يهوياكين ملك يهوذا من السجن.","25:28":"وتلطف به وأكرمه إكراما فوق إكرامه لسائر الملوك الذين معه في بابل،","25:29":"وأبدل ثياب سجنه، فصار ينادم الملك على مائدته بصورة دائمة.","25:30":"وصرف له ملك بابل راتبا يوميا كل أيام حياته."};
